-- stylua: ignore start
return {
  { "aaron", "亚伦 (Yàlún) - 希伯来语，意思是“开明”、“高尚”或“力量之山”。在《圣经》中，亚伦是摩西的哥哥。\n例如：美国职业棒球大联盟的著名球员 Aaron Judge (亚伦·贾吉)。" },
  { "abandoned", "US: /əˈbæn.dn̩d/\nUK: /əˈbæn.dn̩d/\n\n被遗弃的 (bèi yí qì de) - 意思是“被抛弃”、“不再使用”。\n例如：一座被废弃的工厂 (An abandoned factory)。" },
  { "aberdeen", "阿伯丁 (Ābódīng) - 苏格兰东北部的港口城市，以石油工业和渔业闻名。\n例如：阿伯丁大学 (University of Aberdeen)。" },
  { "abilities", "能力 (nénglì) - 指一个人做某事的能力、才能或力量。\n例如：他有很强的学习能力 (He has a strong ability to learn)。" },
  { "ability", "US: /əˈ.bɪl.ɪ.ti/\nUK: N/A\n\n能力 (nénglì) - 指一个人做某事的能力、才能或力量。\n例如：她有能力清楚地解释事情 (She has the ability to explain things clearly)。" },
  { "able", "US: /ˈeɪ.bl̩/\nUK: N/A\n\n能 (néng) - 表示有能力、有才干或有时间做某事。\n例如：他能胜任这项工作 (He is able to do this job well)。" },
  { "aboriginal", "US: /ˌæb.əˈɹɪd͡ʒ.n̩.l̩/\nUK: /ˌæb.əˈɹɪd͡ʒ.n̩.l̩/\n\n土著的 (tǔzhù de) - 指某地区最早的居民。\n例如：澳大利亚土著居民 (Aboriginal Australians)。" },
  { "abortion", "US: /əˈbɔɹ.ʃn̩/\nUK: N/A\n\n堕胎 (duòtāi) - 指人为地中止妊娠。\n例如：关于堕胎的合法性，至今仍有很大的争议 (The legality of abortion is still a matter of great controversy)。" },
  { "about", "US: /əˈbaʊt/\nUK: /əˈbɛʊt/\n\n关于 (guānyú) - 表示“关于”或“在...方面”。\n例如：一本关于历史的书 (A book about history)。" },
  { "above", "US: /əˈbʌv/\nUK: /əˈbʌv/\n\n在...之上 (zài...zhīshàng) - 表示位置高于某物。\n例如：飞机在云层之上飞行 (The plane is flying above the clouds)。" },
  { "abraham", "亚伯拉罕 (Yàbólāhǎn) - 《圣经》中的重要人物，被称为希伯来人的始祖，犹太教、基督教和伊斯兰教的共同先祖。\n例如：美国总统亚伯拉罕·林肯 (Abraham Lincoln)。" },
  { "abroad", "US: /əˈbɹɔd/\nUK: /əˈbɹɔːd/\n\n在国外 (zài guówài) - 表示在或去外国。\n例如：他正在国外出差 (He is currently abroad on business)。" },
  { "absence", "US: /æbˈsɒns/\nUK: /ˈæb.s(ə)n̩s/\n\n缺席 (quēxí) - 表示不在场或缺少。\n例如：他的缺席让大家很担心 (His absence made everyone worry)。" },
  { "absent", "US: /ˈæb.sn̩t/\nUK: /ˈæb.sn̩t/\n\n缺席的 (quēxí de) - 表示不在场的。\n例如：他今天缺席了会议 (He was absent from the meeting today)。" },
  { "absolute", "US: /ˈæb.səˌlut/\nUK: /ˈæb.səˌljuːt/\n\n绝对的 (juéduì de) - 表示完全的、无条件的。\n例如：我对他有绝对的信心 (I have absolute faith in him)。" },
  { "absolutely", "US: /ˈæb.səˌlut.li/\nUK: /æb.səˈl(j)uːt.lɪ/\n\n绝对地 (juéduì de) - 表示完全地、无条件地。\n例如：这绝对是正确的 (This is absolutely correct)。" },
  { "absorption", "US: /æbˈsɔɹp.ʃn̩/\nUK: /əbˈsɔːp.ʃn̩/\n\n吸收 (xīshōu) - 指一个物体吸收另一个物体的过程。\n例如：植物吸收水分 (Plants absorb water)。" },
  { "abstract", "US: N/A\nUK: /ˈæbˌstɹækt/\n\n抽象的 (chōuxiàng de) - 指不具体的、概念性的。\n例如：这是一个非常抽象的概念 (This is a very abstract concept)。" },
  { "abstracts", "摘要 (zhāiyào) - 对文章或报告的简短概括。\n例如：请先阅读摘要 (Please read the abstract first)。" },
  { "abuse", "US: /əˈbjus/\nUK: /əˈbjuːs/\n\n滥用 (lànyòng) - 指不正当地使用或对待。\n例如：滥用权力 (Abuse of power)。" },
  { "academic", "US: /ˌækəˈdɛmɪk/\nUK: N/A\n\n学术的 (xuéshù de) - 与教育、学术或学习有关的。\n例如：他有很高的学术成就 (He has high academic achievements)。" },
  { "academics", "US: /ˌækəˈdɛmɪks/\nUK: /ˌækəˈdɛmɪks/\n\n学者 (xuézhě) - 在大学里从事教学或研究的人。\n例如：许多学者都参加了这次会议 (Many academics attended the conference)。" },
  { "academy", "US: /əˈkæd.ə.mi/\nUK: /əˈkæd.ə.mi/\n\n学院 (xuéyuàn) - 提供专业训练或高等教育的学校。\n例如：他毕业于一所著名的军事学院 (He graduated from a famous military academy)。" },
  { "accent", "US: N/A\nUK: /ˈak.sənt/\n\n口音 (kǒuyīn) - 一个人说话时特有的发音方式。\n例如：他说话带点口音 (He speaks with a slight accent)。" },
  { "accept", "US: /əkˈsɛpt/\nUK: /ækˈsɛpt/\n\n接受 (jiēshòu) - 同意并接收某物。\n例如：我接受你的道歉 (I accept your apology)。" },
  { "acceptable", "US: /æk.ˈsɛp.tə.bəl/\nUK: N/A\n\n可接受的 (kě jiēshòu de) - 令人满意的，可以被接受的。\n例如：这个价格是我们可以接受的 (This price is acceptable to us)。" },
  { "acceptance", "US: /ək.ˈsɛp.təns/\nUK: N/A\n\n接受 (jiēshòu) - 同意或承认某事。\n例如：他对这个计划的接受，让大家都很高兴 (His acceptance of the plan made everyone happy)。" },
  { "accepted", "US: /æk.ˈsɛp.tɪd/\nUK: N/A\n\n公认的 (gōngrèn de) - 被普遍承认或接受的。\n例如：这是一个公认的事实 (This is an accepted fact)。" },
  { "accepting", "US: /əkˈsɛptɪŋ/\nUK: N/A\n\n接受 (jiēshòu) - 正在接受或愿意接受。\n例如：他正在接受新的挑战 (He is accepting new challenges)。" },
  { "accepts", "US: /əkˈsɛpts/\nUK: N/A\n\n接受 (jiēshòu) - 接受（第三人称单数）。\n例如：他接受了我的建议 (He accepts my suggestion)。" },
  { "access", "US: /ˈækˌsɛs/\nUK: /ˈæksɛs/\n\n访问 (fǎngwèn) - 使用或进入的权利或机会。\n例如：你需要密码才能访问这个网站 (You need a password to access this website)。" },
  { "accessed", "访问了 (fǎngwèn le) - 已经访问或进入。\n例如：他昨天访问了那个网站 (He accessed that website yesterday)。" },
  { "accessibility", "US: /ækˌsɛs.əˈbɪl.ət.i/\nUK: /ækˌsɛs.əˈbɪl.ət.i/\n\n可访问性 (kě fǎngwèn xìng) - 指某物容易被访问或使用的程度。\n例如：我们致力于提高网站的可访问性 (We are committed to improving the accessibility of our website)。" },
  { "accessible", "US: /əkˈsɛs.ə.bəl/\nUK: /əkˈsɛs.ə.bəl/\n\n可访问的 (kě fǎngwèn de) - 可以访问或进入的。\n例如：这个网站对所有用户都是可访问的 (This website is accessible to all users)。" },
  { "accessing", "正在访问 (zhèngzài fǎngwèn) - 正在进入或使用。\n例如：他正在访问一个安全的网站 (He is accessing a secure website)。" },
  { "accessories", "配件 (pèijiàn) - 附加到主要设备上的物品。\n例如：这个手机有很多配件 (This phone has many accessories)。" },
  { "accessory", "US: /ækˈsɛsəɹi/\nUK: /ækˈsɛs(ə)ɹi/\n\n配饰 (pèishì) - 用于装饰的物品。\n例如：她戴着漂亮的发饰 (She is wearing a beautiful hair accessory)。" },
  { "accident", "US: /ˈæk.sə.dənt/\nUK: N/A\n\n事故 (shìgù) - 意外发生的、造成损失或伤害的事件。\n例如：他在一起交通事故中受伤了 (He was injured in a traffic accident)。" },
  { "accidents", "事故 (shìgù) - 意外发生的、造成损失或伤害的事件（复数）。\n例如：这里经常发生交通事故 (Traffic accidents often happen here)。" },
  { "accommodate", "US: /əˈkɑməˌdeɪt/\nUK: /əˈkɒməˌdeɪt/\n\n容纳 (róngnà) - 为...提供住宿或空间。\n例如：这个酒店可以容纳200人 (This hotel can accommodate 200 people)。" },
  { "accommodation", "US: N/A\nUK: /ə.ˌkɒm.ə.ˈdeɪ.ʃən/\n\n住宿 (zhùsù) - 指临时居住的地方，如旅馆、酒店等。\n例如：他们为他支付了机票和酒店住宿费用。 (They paid for his flights and hotel accommodation.)" },
  { "accommodations", "住宿 (zhùsù) - (复数) 指临时居住的地方，如旅馆、酒店等。\n例如：我们为所有与会者预订了住宿。 (We have booked accommodations for all attendees.)" },
  { "accompanied", "US: /əˈkʌmpnid/\nUK: N/A\n\n陪同 (péitóng) - 指与某人一同前往或停留。\n例如：旅行中他由妻子陪同。 (His wife accompanied him on the trip.)" },
  { "accompanying", "US: /əˈkʌm.p(ə.)ni.ɪŋ/\nUK: /əˈkʌm.p(ə.)ni.ɪŋ/\n\n伴随的 (bànsuí de) - 指与某事物同时发生或存在。\n例如：抑郁症几乎总是伴有失眠。 (Depression is almost always accompanied by insomnia.)" },
  { "accomplish", "US: /əˈkɑm.plɪʃ/\nUK: /əˈkɐm.plɪʃ/\n\n完成 (wánchéng) - 指成功地做完某事。\n例如：如果我们齐心协力，我想我们能完成我们的目标。 (If we all work together, I think we can accomplish our goal.)" },
  { "accomplished", "US: /ə.ˈkɑm.plɪʃt/\nUK: /ə.ˈkɒm.plɪʃt/\n\n有造诣的 (yǒu zàoyì de) - 形容一个人在特定领域技能高超或才华横溢。\n例如：她是一位很有造诣的钢琴家。 (She is an accomplished pianist.)" },
  { "accordance", "US: /ə.ˈkɔɹd.əns/\nUK: N/A\n\n按照 (ànzhào) - 通常用于“in accordance with”短语中，表示“根据”、“符合”。\n例如：按照她的遗愿，她被安葬在法国。 (In accordance with her wishes, she was buried in France.)" },
  { "according", "US: /ə.ˈkɔɹd.ɪŋ/\nUK: /əˈkɔːdɪŋ/\n\n根据 (gēnjù) - 表示“依据”、“按照”。\n例如：根据我们的记录，你欠我们130美元。 (According to our records, you owe us $130.)" },
  { "accordingly", "US: /ə.ˈkɔɹ.dɪŋ.li/\nUK: /əˈkɔː(ɹ).dɪŋ.li/\n\n因此 (yīncǐ) - 表示“所以”、“结果”。\n例如：这是一个困难的工作，他们应该得到相应的报酬。 (It is a difficult job and they should be paid accordingly.)" },
  { "account", "US: /ə.ˈkaʊnt/\nUK: N/A\n\n账户 (zhànghù) - 指银行账户、用户账号或记录。\n例如：我需要创建一个新账户 (I need to create a new account)。" },
  { "accountability", "US: /ə.ˌkaʊn.tə.ˈbɪl.ət.i/\nUK: /ə.ˌkaʊn.tə.ˈbɪl.ət.i/\n\n问责制 (wènzé zhì) - 指对行为负责的义务。\n例如：公司强调问责制 (The company emphasizes accountability)。" },
  { "accounting", "US: /ə.ˈkaʊn.tɪŋ/\nUK: /ə.ˈkaʊn.tɪŋ/\n\n会计 (kuàijì) - 指记录和报告财务信息的工作。\n例如：她在学习会计 (She is studying accounting)。" },
  { "accounts", "US: /əˈkaʊnts/\nUK: N/A\n\n账目 (zhàngmù) - 账户的复数形式。\n例如：请检查所有账目 (Please check all accounts)。" },
  { "accreditation", "US: [əˌkɹɛd.ɨɾˈeɪ.ʃən]\nUK: [əˌkɹɛd.ɪˈteɪ.ʃən]\n\n认证 (rènzhèng) - 指官方认可或授权。\n例如：这所大学获得了国家认证 (The university has national accreditation)。" },
  { "accredited", "US: /əˈkɹɛd.ɪt.əd/\nUK: /əˈkɹɛd.ɪt.əd/\n\n获得认证的 (huòdé rènzhèng de) - 指经过官方认可的。\n例如：这是一所获得认证的机构 (This is an accredited institution)。" },
  { "accuracy", "US: /ˈæk.jɚ.ə.si/\nUK: [ˈækjʊrəsɪ]\n\n准确性 (zhǔnquè xìng) - 指正确和精确的程度。\n例如：数据的准确性很重要 (The accuracy of the data is important)。" },
  { "accurate", "US: /ˈæk.jə.ɹɪt/\nUK: /ˈæk.jə.ɹɪt/\n\n准确的 (zhǔnquè de) - 指正确无误的。\n例如：这是一个准确的描述 (This is an accurate description)。" },
  { "accurately", "US: /ˈæk.jə.ɹɪt.li/\nUK: /ˈæk.jə.ɹɪt.li/\n\n准确地 (zhǔnquè de) - 指以精确的方式。\n例如：他准确地回答了问题 (He answered the question accurately)。" },
  { "accused", "US: /ə.ˈkjuzd/\nUK: N/A\n\n被指控的 (bèi zhǐkòng de) - 指被指责犯有罪行的。\n例如：被告被指控盗窃 (The accused was charged with theft)。" },
  { "acdbentity", "AutoCAD数据库实体 (AutoCAD shùjùkù shítǐ) - AutoCAD软件中的数据库对象实体，用于表示图形中的各种元素。\n例如：该程序可以处理各种AutoCAD数据库实体 (The program can handle various AutoCAD database entities)。" },
  { "acer", "宏碁 (Hóngqí) - 台湾的一家知名电脑制造商，生产笔记本电脑、台式机和显示器等产品。\n例如：他买了一台宏碁笔记本电脑 (He bought an Acer laptop)。" },
  { "achieve", "US: /əˈtʃiːv/\nUK: /əˈtʃiːv/\n\n实现 (shíxiàn) - 成功地完成或达到某个目标。\n例如：她通过努力工作实现了自己的梦想 (She achieved her dream through hard work)。" },
  { "achieved", "US: /əˈtʃiːvd/\nUK: /əˈtʃiːvd/\n\n已实现的 (yǐ shíxiàn de) - 已经成功完成或达到的。\n例如：他已实现了预期的销售目标 (He has achieved the expected sales target)。" },
  { "achievement", "US: /əˈtʃiːvmənt/\nUK: N/A\n\n成就 (chéngjiù) - 通过努力获得的成功或完成的事情。\n例如：获得诺贝尔奖是他最大的成就 (Winning the Nobel Prize was his greatest achievement)。" },
  { "achievements", "US: /əˈt͡ʃiːvmənts/\nUK: /əˈt͡ʃiːvmənts/\n\n成就 (chéngjiù) - 成就的复数形式。\n例如：她在科学领域取得了许多重要成就 (She has made many important achievements in science)。" },
  { "achieving", "US: /əˈtʃiːvɪŋ/\nUK: /əˈtʃiːvɪŋ/\n\n实现 (shíxiàn) - 正在完成或达到某个目标的过程。\n例如：他正在努力实现自己的目标 (He is working hard at achieving his goals)。" },
  { "acid", "US: /ˈæs.ɪd/\nUK: N/A\n\n酸 (suān) - 一种化学物质，pH值小于7，具有腐蚀性。\n例如：胃酸帮助消化食物 (Stomach acid helps digest food)。" },
  { "acids", "US: /ˈæ.sɪdz/\nUK: /ˈæ.sɪdz/\n\n酸类 (suān lèi) - 酸的复数形式，指多种酸性物质。\n例如：这些酸类物质需要小心处理 (These acids need to be handled carefully)。" },
  { "acknowledge", "US: /ækˈnɑː.lɪdʒ/\nUK: /əkˈnɒ.lɪdʒ/\n\n承认 (chéngrèn) - 接受或承认某事的真实性或存在。\n例如：他承认自己犯了错误 (He acknowledged his mistake)。" },
  { "acknowledged", "公认的 (gōngrèn de) - 被普遍承认或接受的。\n例如：他是公认的专家 (He is an acknowledged expert)。" },
  { "acne", "US: /ˈæk.ni/\nUK: N/A\n\n痤疮 (cuóchuāng) - 一种常见的皮肤问题，通常在青春期出现。\n例如：青少年常常受痤疮困扰 (Teenagers often suffer from acne)。" },
  { "acoustic", "US: /əˈkuːstɪk/\nUK: N/A\n\n声学的 (shēngxué de) - 与声音或听觉相关的。\n例如：他演奏了一首美妙的木吉他曲 (He played a beautiful acoustic guitar song)。" },
  { "acquire", "US: /əˈkwaɪəɹ/\nUK: /əˈkwaɪə/\n\n获得 (huòdé) - 通过努力或购买得到某物。\n例如：公司计划收购一家新企业 (The company plans to acquire a new business)。" },
  { "acquired", "US: /əˈkwaɪɹd/\nUK: /əˈkwaɪəd/\n\n获得的 (huòdé de) - 已经得到或学习到的。\n例如：他在旅行中获得了很多知识 (He acquired a lot of knowledge during his travels)。" },
  { "acquisition", "US: /æ.kwɪ.ˈzɪ.ʃən/\nUK: /æ.kwɪ.ˈzɪ.ʃən/\n\n收购 (shōugòu) - 购买或获得的行为，尤指企业收购。\n例如：这次收购耗资数百万美元 (The acquisition cost millions of dollars)。" },
  { "acquisitions", "收购 (shōugòu) - 收购的复数形式。\n例如：公司今年完成了多次收购 (The company completed multiple acquisitions this year)。" },
  { "acre", "US: /ˈeɪ.kɚ/\nUK: /ˈeɪ.kə/\n\n英亩 (yīngmǔ) - 面积单位，约等于4047平方米。\n例如：这个农场占地50英亩 (The farm covers 50 acres)。" },
  { "acres", "US: /ˈeɪ.kəz/\nUK: /ˈeɪ.kəz/\n\n英亩 (yīngmǔ) - 英亩的复数形式。\n例如：他们拥有数百英亩土地 (They own hundreds of acres of land)。" },
  { "acrobat", "US: /ˈæk.ɹə.bæt/\nUK: /ˈæk.ɹə.bæt/\n\n杂技演员 (zájì yǎnyuán) - 表演体操和平衡技巧的人；也指Adobe的PDF阅读软件。\n例如：这位杂技演员表演了惊人的空中翻转 (The acrobat performed amazing aerial flips)。" },
  { "across", "US: /əˈkɹɔs/\nUK: /əˈkɹɑs/\n\n穿过 (chuānguò) - 从一边到另一边。\n例如：他们走过了那座桥 (They walked across the bridge)。" },
  { "acrylic", "US: /ə.ˈkɹɪ.lɪk/\nUK: /ə.ˈkɹɪ.lɪk/\n\n丙烯酸 (bǐngxīsuān) - 一种合成材料或颜料。\n例如：她用丙烯颜料画画 (She paints with acrylic paints)。" },
  { "acting", "US: /ˈæk.tɪŋ/\nUK: N/A\n\n表演 (biǎoyǎn) - 演戏的艺术或行为；也指代理的、临时的。\n例如：他在学习表演 (He is studying acting)。" },
  { "action", "US: /ˈæk.ʃən/\nUK: N/A\n\n行动 (xíngdòng) - 做某事的过程或行为。\n例如：我们需要立即采取行动 (We need to take action immediately)。" },
  { "actions", "US: /ˈæk.ʃənz/\nUK: N/A\n\n行为 (xíngwéi) - 行动的复数形式。\n例如：他的行为说明了一切 (His actions speak louder than words)。" },
  { "activated", "激活的 (jīhuó de) - 已经启动或触发的。\n例如：该账户已被激活 (The account has been activated)。" },
  { "activation", "US: /æktɪˈveɪʃən/\nUK: /æktɪˈveɪʃən/\n\n激活 (jīhuó) - 启动或启用某物的过程。\n例如：产品激活需要许可证密钥 (Product activation requires a license key)。" },
  { "active", "US: /ˈæk.tɪv/\nUK: N/A\n\n活跃的 (huóyuè de) - 积极参与的或正在运作的。\n例如：他是一个活跃的社区成员 (He is an active community member)。" },
  { "actively", "积极地 (jījí de) - 以活跃或主动的方式。\n例如：她积极参与志愿活动 (She actively participates in volunteer activities)。" },
  { "activists", "活动家 (huódòngjiā) - 积极参与社会或政治运动的人。\n例如：环保活动家呼吁保护森林 (Environmental activists call for forest protection)。" },
  { "activities", "US: /ækˈtɪv.ə.tiz/\nUK: /ækˈtɪ.vɪ.tiz/\n\n活动 (huódòng) - 各种行为或事件的总称。\n例如：学校组织了许多课外活动 (The school organized many extracurricular activities)。" },
  { "activity", "US: /ækˈtɪ.və.ti/\nUK: N/A\n\n活动 (huódòng) - 特定的行为或事件。\n例如：体育活动对健康有益 (Physical activity is beneficial to health)。" },
  { "actor", "US: /ˈæk.tɚ/\nUK: /ˈæk.tə/\n\n演员 (yǎnyuán) - 在电影、戏剧或电视中表演的男性演员。\n例如：他是一位著名的电影演员 (He is a famous movie actor)。" },
  { "actors", "演员 (yǎnyuán) - 演员的复数形式。\n例如：这部电影有很多优秀的演员 (This movie has many excellent actors)。" },
  { "actress", "US: /ˈak.tɹəs/\nUK: /ˈak.tɹəs/\n\n女演员 (nǚ yǎnyuán) - 在电影、戏剧或电视中表演的女性演员。\n例如：她是一位获奖的女演员 (She is an award-winning actress)。" },
  { "acts", "US: /æks/\nUK: /æks/\n\n行为 (xíngwéi) - 行动或法案的复数形式。\n例如：善意的行为能改变世界 (Acts of kindness can change the world)。" },
  { "actual", "US: /ˈæk(t)ʃ(əw)əl/\nUK: /ˈak(t)ʃj(ʊ)əl/\n\n实际的 (shíjì de) - 真实的或确实存在的。\n例如：实际成本比预期高 (The actual cost was higher than expected)。" },
  { "actually", "US: /ˈæk.(t)ʃu.ə.li/\nUK: /-ɪ/\n\n实际上 (shíjì shàng) - 事实上，用于强调真实情况。\n例如：实际上，我已经完成了 (Actually, I have already finished)。" },
  { "acute", "US: /əˈkjut/\nUK: /əˈkjuːt/\n\n急性的 (jíxìng de) - 严重的、尖锐的或突然发作的。\n例如：他患有急性支气管炎 (He has acute bronchitis)。" },
  { "adam", "亚当 (Yàdāng) - 男性名字；《圣经》中的第一个人类。\n例如：亚当是一个常见的英文名 (Adam is a common English name)。" },
  { "adams", "亚当斯 (Yàdāngsī) - 常见的英文姓氏。\n例如：约翰·亚当斯是美国第二任总统 (John Adams was the second U.S. President)。" },
  { "adaptation", "US: /ˌædæpˈteɪʃən/\nUK: /ˌædæpˈteɪʃən/\n\n改编 (gǎibiān) - 对某物进行调整以适应新情况。\n例如：这部电影是小说的改编 (This movie is an adaptation of the novel)。" },
  { "adapted", "US: /əˈdæptɪd/\nUK: N/A\n\n改编的 (gǎibiān de) - 已经调整或修改的。\n例如：这个故事被改编成了电视剧 (The story was adapted into a TV series)。" },
  { "adapter", "US: /əˈdaptə/\nUK: /əˈdaptə/\n\n适配器 (shìpèiqì) - 用于连接不同设备的装置。\n例如：我需要一个电源适配器 (I need a power adapter)。" },
  { "adapters", "适配器 (shìpèiqì) - 适配器的复数形式。\n例如：这些适配器兼容多种设备 (These adapters are compatible with multiple devices)。" },
  { "adaptive", "US: /əˈdæp.tɪv/\nUK: /əˈdæp.tɪv/\n\n自适应的 (zì shìyìng de) - 能够调整以适应变化的。\n例如：该系统具有自适应学习功能 (The system has adaptive learning capabilities)。" },
  { "adaptor", "适配器 (shìpèiqì) - adapter的另一种拼写。\n例如：请使用正确的适配器 (Please use the correct adaptor)。" },
  { "added", "US: [ˈæɾ.əd]\nUK: [ˈad.əd]\n\n添加的 (tiānjiā de) - 已经加入或增加的。\n例如：新功能已添加到应用中 (New features have been added to the app)。" },
  { "addiction", "US: /əˈdɪkʃən/\nUK: /əˈdɪkʃən/\n\n上瘾 (shàngyǐn) - 对某物的强烈依赖或沉迷。\n例如：他正在戒除烟瘾 (He is overcoming his smoking addiction)。" },
  { "adding", "US: /ˈæ.dɪŋ/\nUK: N/A\n\n添加 (tiānjiā) - 正在增加或加入。\n例如：我正在添加更多信息 (I am adding more information)。" },
  { "addition", "US: /æˈdɪʃən/\nUK: N/A\n\n增加 (zēngjiā) - 加入新事物的行为；加法运算。\n例如：除此之外，我们还需要更多时间 (In addition, we need more time)。" },
  { "additional", "US: /əˈdɪʃənəl/\nUK: N/A\n\n额外的 (éwài de) - 更多的或补充的。\n例如：我们需要额外的资源 (We need additional resources)。" },
  { "additionally", "此外 (cǐwài) - 除了已经提到的之外。\n例如：此外，项目还需要更多资金 (Additionally, the project needs more funding)。" },
  { "additions", "US: /əˈdɪʃənz/\nUK: N/A\n\n增加物 (zēngjiā wù) - 增加的事物或部分。\n例如：房屋的增加部分包括一个新车库 (The additions to the house include a new garage)。" },
  { "address", "US: /æˈdɹɛs/\nUK: /əˈdɹɛs/\n\n地址 (dìzhǐ) - 居住或办公地点；也指处理或解决问题。\n例如：请提供你的邮寄地址 (Please provide your mailing address)。" },
  { "addressed", "US: /əˈdɹɛst/\nUK: /əˈdɹɛst/\n\n已解决的 (yǐ jiějué de) - 已经处理或提到的。\n例如：这个问题已被解决 (The issue has been addressed)。" },
  { "addresses", "US: /əˈdɹɛsɪz/\nUK: /əˈdɹɛsɪz/\n\n地址 (dìzhǐ) - 地址的复数形式；也指演讲或处理。\n例如：请更新所有电子邮件地址 (Please update all email addresses)。" },
  { "addressing", "US: /əˈdɹɛsɪŋ/\nUK: N/A\n\n处理 (chǔlǐ) - 正在解决或谈论。\n例如：我们正在处理这个问题 (We are addressing this issue)。" },
  { "adds", "US: /ædz/\nUK: N/A\n\n增加 (zēngjiā) - 添加或加上（第三人称单数）。\n例如：这个功能增加了便利性 (This feature adds convenience)。" },
  { "adelaide", "阿德莱德 (Ādéláidé) - 澳大利亚南澳大利亚州的首府城市。\n例如：阿德莱德以其葡萄酒产业闻名 (Adelaide is famous for its wine industry)。" },
  { "adequate", "足够的 (zúgòu de) - 数量或质量满足需求的。\n例如：我们有足够的资源完成项目 (We have adequate resources to complete the project)。" },
  { "adidas", "阿迪达斯 (Ādídásī) - 德国著名运动品牌，生产运动鞋、服装和配件。\n例如：他穿着一双阿迪达斯运动鞋 (He wore a pair of Adidas sneakers)。" },
  { "adipex", "阿地芬 (Ādìfēn) - 一种处方减肥药物的商品名。\n例如：医生为她开了阿地芬处方 (The doctor prescribed Adipex for her)。" },
  { "adjacent", "US: /əˈdʒeɪ.sənt/\nUK: /əˈdʒeɪ.sənt/\n\n相邻的 (xiānglín de) - 紧挨着的或附近的。\n例如：他们的房子与我们的相邻 (Their house is adjacent to ours)。" },
  { "adjust", "US: /əˈdʒʌst/\nUK: /əˈdʒʌst/\n\n调整 (tiáozhěng) - 改变以适应新情况。\n例如：请调整你的时间表 (Please adjust your schedule)。" },
  { "adjustable", "可调节的 (kě tiáojié de) - 可以改变或修改的。\n例如：这把椅子是可调节高度的 (This chair has an adjustable height)。" },
  { "adjusted", "US: /əˈdʒʌstɪd/\nUK: /əˈdʒʌstɪd/\n\n调整后的 (tiáozhěng hòu de) - 已经修改或适应的。\n例如：价格已根据通货膨胀调整 (The price has been adjusted for inflation)。" },
  { "adjustment", "US: /əˈdʒʌst.mənt/\nUK: N/A\n\n调整 (tiáozhěng) - 进行改变的行为或结果。\n例如：我们需要对计划做一些调整 (We need to make some adjustments to the plan)。" },
  { "adjustments", "调整 (tiáozhěng) - 调整的复数形式。\n例如：系统需要多次调整 (The system needs several adjustments)。" },
  { "admin", "US: /ədˈmɪn/\nUK: /ədˈmɪn/\n\n管理员 (guǎnlǐyuán) - administrator的缩写，管理系统或网站的人。\n例如：请联系管理员获取权限 (Please contact the admin for permissions)。" },
  { "administered", "管理的 (guǎnlǐ de) - 已经管理或执行的。\n例如：该项目由政府管理 (The project was administered by the government)。" },
  { "administration", "管理 (guǎnlǐ) - 管理组织或执行任务；也指政府。\n例如：公司管理层做出了决定 (The company administration made the decision)。" },
  { "administrative", "行政的 (xíngzhèng de) - 与管理或行政工作相关的。\n例如：她从事行政工作 (She does administrative work)。" },
  { "administrator", "管理员 (guǎnlǐyuán) - 管理系统、组织或财产的人。\n例如：系统管理员负责维护服务器 (The system administrator maintains the servers)。" },
  { "administrators", "管理员 (guǎnlǐyuán) - 管理员的复数形式。\n例如：所有管理员都收到了通知 (All administrators received the notification)。" },
  { "admission", "入场 (rùchǎng) - 进入某地或被接纳的权利；也指承认。\n例如：博物馆门票免费 (Admission to the museum is free)。" },
  { "admissions", "招生 (zhāoshēng) - 接纳新成员的过程，尤指学校招生。\n例如：大学招生办公室很忙 (The university admissions office is busy)。" },
  { "admit", "承认 (chéngrèn) - 接受事实为真或允许进入。\n例如：他承认自己错了 (He admitted he was wrong)。" },
  { "admitted", "被接纳的 (bèi jiēnà de) - 已经被允许进入或承认的。\n例如：她被哈佛大学录取了 (She was admitted to Harvard University)。" },
  { "adobe", "Adobe公司 (Adobe gōngsī) - 美国软件公司，以Photoshop、PDF等产品著名；也指土坯。\n例如：我用Adobe Photoshop编辑图片 (I edit images with Adobe Photoshop)。" },
  { "adolescent", "青少年 (qīngshàonián) - 处于青春期的年轻人。\n例如：青少年需要指导和支持 (Adolescents need guidance and support)。" },
  { "adopt", "采用 (cǎiyòng) - 接受并开始使用；也指收养。\n例如：公司采用了新策略 (The company adopted a new strategy)。" },
  { "adopted", "采用的 (cǎiyòng de) - 已经接受或收养的。\n例如：他们收养了一个孩子 (They adopted a child)。" },
  { "adoption", "采用 (cǎiyòng) - 采纳或收养的行为。\n例如：新技术的采用需要时间 (The adoption of new technology takes time)。" },
  { "adrian", "阿德里安 (Ādélǐ'ān) - 常见的英文男性名字。\n例如：阿德里安是我的同事 (Adrian is my colleague)。" },
  { "adsl", "非对称数字用户线路 (fēi duìchèn shùzì yònghù xiànlù) - 一种宽带互联网连接技术，缩写为ADSL。\n例如：我们使用ADSL上网 (We use ADSL for internet access)。" },
  { "adult", "成年人 (chéngniánrén) - 已经成熟的人，通常指18岁以上。\n例如：这部电影仅供成年人观看 (This movie is for adults only)。" },
  { "adults", "成年人 (chéngniánrén) - 成年人的复数形式。\n例如：成年人需要为自己的行为负责 (Adults are responsible for their own actions)。" },
  { "advance", "前进 (qiánjìn) - 向前移动或提前；也指进步。\n例如：我们需要提前预订 (We need to book in advance)。" },
  { "advanced", "先进的 (xiānjìn de) - 高级的或发达的。\n例如：他学习高级数学 (He studies advanced mathematics)。" },
  { "advancement", "进步 (jìnbù) - 向前发展或提升。\n例如：技术进步改变了我们的生活 (Technological advancement has changed our lives)。" },
  { "advances", "进展 (jìnzhǎn) - 前进或进步的复数形式。\n例如：医学取得了重大进展 (Medicine has made significant advances)。" },
  { "advantage", "优势 (yōushì) - 有利条件或好处。\n例如：这给了我们竞争优势 (This gives us a competitive advantage)。" },
  { "advantages", "优势 (yōushì) - 优势的复数形式。\n例如：这个方案有很多优势 (This plan has many advantages)。" },
  { "adventure", "冒险 (màoxiǎn) - 令人兴奋或危险的经历。\n例如：他们去亚马逊探险 (They went on an adventure to the Amazon)。" },
  { "adventures", "冒险 (màoxiǎn) - 冒险的复数形式。\n例如：他写了一本关于他冒险经历的书 (He wrote a book about his adventures)。" },
  { "adverse", "不利的 (bùlì de) - 有害的或不想要的。\n例如：药物可能有不利副作用 (The medicine may have adverse side effects)。" },
  { "advert", "广告 (guǎnggào) - advertisement的缩写，尤其在英式英语中使用。\n例如：我在报纸上看到了一则招聘广告 (I saw a job advert in the newspaper)。" },
  { "advertise", "打广告 (dǎ guǎnggào) - 公开宣传产品或服务。\n例如：公司在电视上打广告 (The company advertises on TV)。" },
  { "advertisement", "广告 (guǎnggào) - 用于推广产品或服务的公告。\n例如：这个广告很有创意 (This advertisement is very creative)。" },
  { "advertisements", "广告 (guǎnggào) - 广告的复数形式。\n例如：报纸上有很多广告 (There are many advertisements in the newspaper)。" },
  { "advertiser", "广告商 (guǎnggào shāng) - 付费做广告的个人或公司。\n例如：广告商支付了高额费用 (The advertiser paid a high fee)。" },
  { "advertisers", "广告商 (guǎnggào shāng) - 广告商的复数形式。\n例如：许多广告商参加了会议 (Many advertisers attended the conference)。" },
  { "advertising", "广告业 (guǎnggào yè) - 广告的行业或活动。\n例如：她在广告业工作 (She works in advertising)。" },
  { "advice", "建议 (jiànyì) - 对某人应该做什么的意见。\n例如：我需要你的建议 (I need your advice)。" },
  { "advise", "建议 (jiànyì) - 给予建议或劝告。\n例如：我建议你早点出发 (I advise you to leave early)。" },
  { "advised", "被告知的 (bèi gàozhī de) - 已经得到建议或通知的。\n例如：他被告知要小心 (He was advised to be careful)。" },
  { "advisor", "顾问 (gùwèn) - 提供建议的人。\n例如：他是我的学术顾问 (He is my academic advisor)。" },
  { "advisors", "顾问 (gùwèn) - 顾问的复数形式。\n例如：公司有多位财务顾问 (The company has several financial advisors)。" },
  { "advisory", "顾问的 (gùwèn de) - 提供建议的；也指咨询委员会。\n例如：顾问委员会开会了 (The advisory board met)。" },
  { "advocacy", "US: /ˈæd.və.kə.si/\nUK: /ˈæd.və.kə.si/\n\n倡导 (chàngdǎo) - 公开支持某个事业或政策。\n例如：她从事环保倡导工作 (She works in environmental advocacy)。" },
  { "advocate", "US: /ˈæd.və.keɪt/\nUK: /ˈæd.və.keɪt/\n\n提倡 (tíchàng) - 公开支持或推荐；也指辩护人。\n例如：他提倡改革 (He advocates for reform)。" },
  { "adware", "广告软件 (guǎnggào ruǎnjiàn) - 自动显示广告的软件。\n例如：这个程序包含广告软件 (This program contains adware)。" },
  { "aerial", "US: /ˈɛː.ɹi.əl/\nUK: /ˈɛː.ɹi.əl/\n\n空中的 (kōngzhōng de) - 在空中的或与飞行相关的。\n例如：无人机进行了空中拍摄 (The drone took aerial photographs)。" },
  { "aerospace", "航空航天 (hángkōng hángtiān) - 与飞机和航天器相关的工业。\n例如：他在航空航天公司工作 (He works for an aerospace company)。" },
  { "affair", "US: /əˈfɛə(ɹ)/\nUK: /əˈfɛə/\n\n事务 (shìwù) - 事件或情况；也指婚外情。\n例如：这是私人事务 (This is a private affair)。" },
  { "affairs", "US: /əˈfɛɹz/\nUK: /əˈfɛəz/\n\n事务 (shìwù) - 事务的复数形式。\n例如：外交事务很复杂 (Foreign affairs are complex)。" },
  { "affect", "US: /əˈfɛkt/\nUK: /əˈfɛkt/\n\n影响 (yǐngxiǎng) - 对某事物产生作用或改变。\n例如：天气会影响我们的计划 (The weather will affect our plans)。" },
  { "affected", "US: /əˈfɛktɪd/\nUK: N/A\n\n受影响的 (shòu yǐngxiǎng de) - 已经被影响的。\n例如：许多人受到了洪水的影响 (Many people were affected by the flood)。" },
  { "affecting", "US: /əˈfɛktɪŋ/\nUK: N/A\n\n影响 (yǐngxiǎng) - 正在产生影响。\n例如：这个问题正在影响我们的业务 (This issue is affecting our business)。" },
  { "affects", "影响 (yǐngxiǎng) - 影响（第三人称单数）。\n例如：压力影响健康 (Stress affects health)。" },
  { "affiliate", "US: /əˈfɪl.i.et/\nUK: /əˈfɪl.i.et/\n\n附属机构 (fùshǔ jīgòu) - 与较大组织有联系的组织；也指关联方。\n例如：这是我们的附属公司 (This is our affiliate company)。" },
  { "affiliated", "附属的 (fùshǔ de) - 与组织有正式联系的。\n例如：他附属于那所大学 (He is affiliated with that university)。" },
  { "affiliates", "附属机构 (fùshǔ jīgòu) - 附属机构的复数形式。\n例如：公司在全球有多个附属机构 (The company has affiliates worldwide)。" },
  { "affiliation", "US: /əˌfɪliˈeɪʃən/\nUK: /əˌfɪliˈeɪʃən/\n\n隶属关系 (lìshǔ guānxì) - 与组织的正式联系。\n例如：请注明你的机构隶属关系 (Please state your institutional affiliation)。" },
  { "afford", "US: /əˈfoɹd/\nUK: /əˈfɔːd/\n\n负担得起 (fùdān dé qǐ) - 有足够的钱购买；也指提供。\n例如：我买不起这辆车 (I cannot afford this car)。" },
  { "affordable", "US: /əˈfɔː(ɹ).də.bəl/\nUK: /əˈfɔː(ɹ).də.bəl/\n\n负担得起的 (fùdān dé qǐ de) - 价格合理的。\n例如：我们需要负担得起的住房 (We need affordable housing)。" },
  { "afghanistan", "阿富汗 (Āfùhàn) - 亚洲中部国家。\n例如：阿富汗是一个多山的国家 (Afghanistan is a mountainous country)。" },
  { "afraid", "US: /əˈfɹeɪd/\nUK: N/A\n\n害怕的 (hàipà de) - 感到恐惧或担心。\n例如：我害怕黑暗 (I am afraid of the dark)。" },
  { "africa", "非洲 (Fēizhōu) - 世界第二大洲。\n例如：非洲有丰富的野生动物 (Africa has abundant wildlife)。" },
  { "african", "非洲的 (Fēizhōu de) - 来自或与非洲相关的。\n例如：他研究非洲历史 (He studies African history)。" },
  { "after", "US: /ˈæf.tɚ/\nUK: /ˈæf.tə(ɹ)/\n\n在...之后 (zài...zhīhòu) - 表示时间或顺序的后面。\n例如：午饭后我们去散步 (We go for a walk after lunch)。" },
  { "afternoon", "US: /ˌæf.tɚ.ˈnun/\nUK: /ˌɑːf.tə.ˈnuːn/\n\n下午 (xiàwǔ) - 中午到傍晚之间的时间。\n例如：我们下午见 (See you in the afternoon)。" },
  { "afterwards", "US: /ˈæf.tɚ.wɚdz/\nUK: /ˈɑːftə.wədz/\n\n后来 (hòulái) - 在那之后。\n例如：我们先吃饭，后来看了电影 (We ate first, and watched a movie afterwards)。" },
  { "again", "US: N/A\nUK: /əˈɡeɪn/\n\n再次 (zàicì) - 又一次，重复。\n例如：请再说一遍 (Please say it again)。" },
  { "against", "US: /əˈɡɛnst/\nUK: /əˈɡeɪnst/\n\n反对 (fǎnduì) - 与...相对或相反。\n例如：我们反对这个决定 (We are against this decision)。" },
  { "aged", "US: /eɪdʒd/\nUK: /eɪdʒd/\n\n年老的 (niánlǎo de) - 特定年龄的或年老的。\n例如：她照顾年老的父母 (She cares for her aged parents)。" },
  { "agencies", "机构 (jīgòu) - 机构的复数形式。\n例如：政府机构负责监管 (Government agencies are responsible for regulation)。" },
  { "agency", "US: /ˈeɪ.dʒən.si/\nUK: N/A\n\n机构 (jīgòu) - 提供特定服务的组织。\n例如：我通过旅行社预订了机票 (I booked tickets through a travel agency)。" },
  { "agenda", "US: /əˈdʒɛn.də/\nUK: N/A\n\n议程 (yìchéng) - 会议的议题列表或计划。\n例如：今天的会议议程是什么？ (What is today's agenda?)。" },
  { "agent", "US: /ˈeɪ.dʒənt/\nUK: N/A\n\n代理人 (dàilǐrén) - 代表他人行事的人；也指特工。\n例如：房地产代理帮我们找房子 (The real estate agent helped us find a house)。" },
  { "agents", "US: /ˈeɪ.dʒənts/\nUK: N/A\n\n代理人 (dàilǐrén) - 代理人的复数形式。\n例如：保险代理人提供咨询服务 (Insurance agents provide consulting services)。" },
  { "ages", "US: /ˈeɪ.dʒɪz/\nUK: N/A\n\n年龄 (niánlíng) - 年龄的复数形式；也指很长时间。\n例如：我们等了好久 (We waited for ages)。" },
  { "aggregate", "总计 (zǒngjì) - 总和或集合；也指合计的。\n例如：总销售额达到了一百万 (The aggregate sales reached one million)。" },
  { "aggressive", "US: /əˈɡɹɛs.ɪv/\nUK: N/A\n\n激进的 (jījìn de) - 好斗的或积极进取的。\n例如：公司采取了激进的扩张策略 (The company adopted an aggressive expansion strategy)。" },
  { "aging", "US: /ˈeɪ.dʒɪŋ/\nUK: /ˈeɪ.dʒɪŋ/\n\n老化 (lǎohuà) - 变老的过程。\n例如：人口老化是一个社会问题 (Population aging is a social issue)。" },
  { "agree", "US: /əˈɡɹi/\nUK: N/A\n\n同意 (tóngyì) - 有相同的意见或接受。\n例如：我同意你的观点 (I agree with your opinion)。" },
  { "agreed", "US: /ə.ɡɹi.ːd/\nUK: N/A\n\n同意的 (tóngyì de) - 已经达成一致的。\n例如：我们已达成共识 (We have agreed)。" },
  { "agreement", "US: /əˈɡɹiːmənt/\nUK: N/A\n\n协议 (xiéyì) - 正式的约定或合同。\n例如：双方签署了协议 (Both parties signed the agreement)。" },
  { "agreements", "协议 (xiéyì) - 协议的复数形式。\n例如：我们有多个贸易协议 (We have multiple trade agreements)。" },
  { "agrees", "US: /əˈɡɹiːz/\nUK: /əˈɡɹiːz/\n\n同意 (tóngyì) - 同意（第三人称单数）。\n例如：他同意这个提议 (He agrees with the proposal)。" },
  { "agricultural", "US: /ˌæɡɹɪˈkʌlt͡ʃəɹəl/\nUK: /ˌæɡɹɪˈkʌltjʊəɹəl/\n\n农业的 (nóngyè de) - 与农业或耕作相关的。\n例如：这个地区以农业生产为主 (This region is primarily agricultural)。" },
  { "agriculture", "US: /ˈæɡɹɪˌkʌltʃɚ/\nUK: /ˈæɡɹɪˌkʌltʃə/\n\n农业 (nóngyè) - 种植作物和饲养动物的科学或实践。\n例如：农业是国家经济的基础 (Agriculture is the foundation of the national economy)。" },
  { "ahead", "US: /əˈhɛd/\nUK: N/A\n\n在前面 (zài qiánmiàn) - 在前方或提前。\n例如：你走在我前面 (You are ahead of me)。" },
  { "aids", "US: /eɪdz/\nUK: /eɪdz/\n\n艾滋病 (àizībìng) - 获得性免疫缺陷综合症的缩写；也指帮助。\n例如：预防艾滋病很重要 (Preventing AIDS is important)。" },
  { "aimed", "US: /eɪmd/\nUK: N/A\n\n针对的 (zhēnduì de) - 已经瞄准或针对的。\n例如：这个项目针对年轻人 (The project is aimed at young people)。" },
  { "aims", "US: /eɪmz/\nUK: /eɪmz/\n\n目标 (mùbiāo) - 目的或意图的复数形式。\n例如：我们的目标是提高质量 (Our aims are to improve quality)。" },
  { "aircraft", "US: /ɛəɹ.kɹæft/\nUK: /ɛə.kɹɑːft/\n\n飞机 (fēijī) - 能够飞行的交通工具。\n例如：这架飞机可载客200人 (This aircraft can carry 200 passengers)。" },
  { "airfare", "机票价格 (jīpiào jiàgé) - 乘坐飞机的费用。\n例如：机票价格很贵 (The airfare is expensive)。" },
  { "airline", "航空公司 (hángkōng gōngsī) - 提供航空运输服务的公司。\n例如：我在这家航空公司订了票 (I booked with this airline)。" },
  { "airlines", "航空公司 (hángkōng gōngsī) - 航空公司的复数形式。\n例如：许多航空公司提供国际航班 (Many airlines offer international flights)。" },
  { "airplane", "US: /ˈɛəɹˌpleɪ̯n/\nUK: /ˈɛəpleɪn/\n\n飞机 (fēijī) - 有翼的飞行器。\n例如：我们乘飞机去巴黎 (We took an airplane to Paris)。" },
  { "airport", "US: /ˈɛɹ.pɔɹt/\nUK: /ˈɛə.pɔːt/\n\n机场 (jīchǎng) - 飞机起降的设施。\n例如：我们在机场见面 (We meet at the airport)。" },
  { "airports", "US: /ˈɛə.pɔːts/\nUK: /ˈɛə.pɔːts/\n\n机场 (jīchǎng) - 机场的复数形式。\n例如：这个城市有两个机场 (The city has two airports)。" },
  { "alabama", "阿拉巴马州 (Ālābāmǎ zhōu) - 美国东南部的一个州。\n例如：阿拉巴马州以音乐闻名 (Alabama is famous for its music)。" },
  { "alan", "艾伦 (Àilún) - 常见的英文男性名字。\n例如：艾伦是我的朋友 (Alan is my friend)。" },
  { "alarm", "US: /əˈlɑɹm/\nUK: /əˈlɑːm/\n\n警报 (jǐngbào) - 警告危险的信号或装置。\n例如：火灾警报响了 (The fire alarm went off)。" },
  { "alaska", "阿拉斯加州 (Ālāsījiā zhōu) - 美国最北端的州。\n例如：阿拉斯加州以冰川著名 (Alaska is famous for its glaciers)。" },
  { "albania", "阿尔巴尼亚 (Ā'ěrbāníyà) - 欧洲东南部国家。\n例如：阿尔巴尼亚位于巴尔干半岛 (Albania is located in the Balkans)。" },
  { "albany", "奥尔巴尼 (Ào'ěrbāní) - 纽约州首府城市。\n例如：奥尔巴尼是纽约州的政治中心 (Albany is the political center of New York State)。" },
  { "albert", "阿尔伯特 (Ā'ěrbótè) - 常见的英文男性名字。\n例如：阿尔伯特·爱因斯坦是著名物理学家 (Albert Einstein was a famous physicist)。" },
  { "alberta", "阿尔伯塔省 (Ā'ěrbótǎ shěng) - 加拿大西部省份。\n例如：阿尔伯塔省盛产石油 (Alberta produces abundant oil)。" },
  { "album", "US: /ˈælbəm/\nUK: /ˈælbəm/\n\n专辑 (zhuānjí) - 音乐或照片的集合。\n例如：他们发布了新专辑 (They released a new album)。" },
  { "albums", "专辑 (zhuānjí) - 专辑的复数形式。\n例如：这位歌手有很多畅销专辑 (This singer has many best-selling albums)。" },
  { "albuquerque", "阿尔伯克基 (Ā'ěrbókèjī) - 美国新墨西哥州最大城市。\n例如：阿尔伯克基以热气球节闻名 (Albuquerque is famous for its balloon festival)。" },
  { "alcohol", "US: /ˈæl.kə.hɑl/\nUK: /ˈæl.kə.hɒl/\n\n酒精 (jiǔjīng) - 含有乙醇的饮料或化学物质。\n例如：过量饮酒对健康有害 (Excessive alcohol consumption is harmful to health)。" },
  { "alert", "US: /əˈlɝt/\nUK: /əˈlɜːt/\n\n警报 (jǐngbào) - 警告或保持警惕的；也指警告通知。\n例如：系统发出了安全警报 (The system issued a security alert)。" },
  { "alerts", "警报 (jǐngbào) - 警报的复数形式。\n例如：我收到了多个新闻警报 (I received multiple news alerts)。" },
  { "alex", "亚历克斯 (Yàlìkèsī) - 常见的英文名字，可用于男女。\n例如：亚历克斯是我的同学 (Alex is my classmate)。" },
  { "alexander", "亚历山大 (Yàlìshāndà) - 常见的英文男性名字。\n例如：亚历山大大帝是古代征服者 (Alexander the Great was an ancient conqueror)。" },
  { "alexandria", "亚历山大港 (Yàlìshāndàgǎng) - 埃及北部港口城市。\n例如：亚历山大港有著名的古代图书馆 (Alexandria had a famous ancient library)。" },
  { "alfred", "阿尔弗雷德 (Ā'ěrfúléidé) - 常见的英文男性名字。\n例如：阿尔弗雷德·希区柯克是著名导演 (Alfred Hitchcock was a famous director)。" },
  { "algebra", "US: /ˈæl.dʒə.bɹə/\nUK: /ˈæl.dʒɪ.bɹə/\n\n代数 (dàishù) - 数学的一个分支，使用符号表示数量。\n例如：他在学习代数 (He is studying algebra)。" },
  { "algeria", "阿尔及利亚 (Ā'ěrjílìyà) - 北非国家。\n例如：阿尔及利亚是非洲最大的国家 (Algeria is Africa's largest country)。" },
  { "algorithm", "US: /ˈælɡəˌɹɪðm̩/\nUK: /ˈælɡəɹɪðm̩/\n\n算法 (suànfǎ) - 解决问题的一系列步骤或规则。\n例如：这个算法很有效 (This algorithm is very efficient)。" },
  { "algorithms", "US: /ˈæl.ɡə.ɹɪðmz/\nUK: /ˈæl.ɡə.ɹɪðmz/\n\n算法 (suànfǎ) - 算法的复数形式。\n例如：机器学习使用复杂的算法 (Machine learning uses complex algorithms)。" },
  { "alias", "US: /ˈeɪ.li.əs/\nUK: /ˈeɪ.li.əs/\n\n别名 (biémíng) - 假名或另一个名字。\n例如：他使用别名发表文章 (He publishes articles under an alias)。" },
  { "alice", "爱丽丝 (Àilìsī) - 常见的英文女性名字。\n例如：《爱丽丝梦游仙境》是经典童话 (Alice in Wonderland is a classic fairy tale)。" },
  { "alien", "US: /ˈeɪ.li.ən/\nUK: N/A\n\n外星人 (wàixīngrén) - 来自其他星球的生物；也指外国人。\n例如：科幻电影中常出现外星人 (Aliens often appear in science fiction movies)。" },
  { "align", "US: /æˈlaɪn/\nUK: /æˈlaɪn/\n\n对齐 (duìqí) - 排成直线或使一致。\n例如：请对齐文本 (Please align the text)。" },
  { "alignment", "US: [əˈɫaɪnmənt]\nUK: N/A\n\n对齐 (duìqí) - 排列成直线或一致性。\n例如：确保轮胎对齐正确 (Ensure proper wheel alignment)。" },
  { "alike", "US: /əˈlaɪk/\nUK: /əˈlaɪk/\n\n相似的 (xiāngsì de) - 以相同的方式或相似。\n例如：这两个问题很相似 (These two problems are alike)。" },
  { "alive", "US: /əˈlaɪv/\nUK: N/A\n\n活着的 (huózhe de) - 有生命的或活跃的。\n例如：他还活着 (He is still alive)。" },
  { "allah", "真主 (Zhēnzhǔ) - 伊斯兰教中对上帝的称呼。\n例如：穆斯林信仰真主 (Muslims believe in Allah)。" },
  { "allan", "艾伦 (Àilún) - 常见的英文男性名字，Allan的另一拼写。\n例如：艾伦在公司工作 (Allan works at the company)。" },
  { "alleged", "被指称的 (bèi zhǐchēng de) - 被声称但未证实的。\n例如：他是被指称的嫌疑人 (He is the alleged suspect)。" },
  { "allen", "艾伦 (Àilún) - 常见的英文姓氏或名字。\n例如：艾伦先生是我们的老师 (Mr. Allen is our teacher)。" },
  { "allergy", "US: [ˈæl.ə.dʒi]\nUK: [ˈæl.ə.dʒi]\n\n过敏 (guòmǐn) - 对某种物质的不良反应。\n例如：她对花粉过敏 (She has a pollen allergy)。" },
  { "alliance", "US: /əˈlaɪ.əns/\nUK: /əˈlaɪ.əns/\n\n联盟 (liánméng) - 为共同目标而结成的组织。\n例如：两国建立了军事联盟 (The two countries formed a military alliance)。" },
  { "allied", "US: /əˈlaɪd/\nUK: /əˈlaɪd/\n\n联合的 (liánhé de) - 结成联盟的。\n例如：联合军队取得了胜利 (The allied forces achieved victory)。" },
  { "allocated", "US: /ˈæl.ə.keɪ.tɪd/\nUK: /ˈæl.ə.keɪ.tɪd/\n\n分配的 (fēnpèi de) - 已经指定或分配的。\n例如：资源已被分配给各部门 (Resources have been allocated to each department)。" },
  { "allocation", "分配 (fēnpèi) - 分配资源或任务的行为。\n例如：预算分配需要仔细规划 (Budget allocation requires careful planning)。" },
  { "allow", "US: /əˈlaʊ/\nUK: /əˈlaʊ/\n\n允许 (yǔnxǔ) - 给予许可或使某事成为可能。\n例如：请允许我解释 (Please allow me to explain)。" },
  { "allowance", "US: /əˈlaʊəns/\nUK: N/A\n\n津贴 (jīntiē) - 定期给予的金钱；也指容许的范围。\n例如：孩子们每周都有零花钱 (Children get a weekly allowance)。" },
  { "allowed", "US: /əˈlaʊd/\nUK: N/A\n\n被允许的 (bèi yǔnxǔ de) - 已经获得许可的。\n例如：这里不允许吸烟 (Smoking is not allowed here)。" },
  { "allowing", "US: /əˈlaʊɪŋ/\nUK: N/A\n\n允许 (yǔnxǔ) - 正在给予许可。\n例如：法律允许言论自由 (The law is allowing freedom of speech)。" },
  { "allows", "US: /əˈlaʊz/\nUK: /əˈlaʊz/\n\n允许 (yǔnxǔ) - 允许（第三人称单数）。\n例如：这个应用允许你编辑照片 (This app allows you to edit photos)。" },
  { "alloy", "合金 (héjīn) - 两种或多种金属的混合物。\n例如：钢是铁和碳的合金 (Steel is an alloy of iron and carbon)。" },
  { "almost", "US: /ˈɑl.moʊst/\nUK: /ɔːl.ˈməʊst/\n\n几乎 (jīhū) - 接近但不完全。\n例如：我几乎忘了这件事 (I almost forgot about it)。" },
  { "alone", "US: /əˈloʊn/\nUK: /əˈləʊn/\n\n独自 (dúzì) - 单独地，没有他人陪伴。\n例如：她独自生活 (She lives alone)。" },
  { "along", "US: /əˈlɔŋ/\nUK: /əˈlɑŋ/\n\n沿着 (yánzhe) - 顺着某个方向。\n例如：我们沿着河边散步 (We walk along the river)。" },
  { "alot", "很多 (hěnduō) - a lot的拼写错误，但常见用法指很多。\n例如：这是一个很多人犯的拼写错误 (This is a spelling mistake that alot of people make)。" },
  { "alpha", "US: /ˈælfə/\nUK: N/A\n\n阿尔法 (Ā'ěrfǎ) - 希腊字母表的第一个字母；也指初始版本或领导者。\n例如：这是软件的alpha版本 (This is the alpha version of the software)。" },
  { "alphabetical", "US: /ˌælfəˈbɛtɪkəl/\nUK: /ˌæl.fəˈbɛt.ɪ.kəl/\n\n按字母顺序的 (àn zìmǔ shùnxù de) - 按照字母表排列的。\n例如：请按字母顺序排列这些名字 (Please arrange these names in alphabetical order)。" },
  { "alpine", "US: /ˈæl.paɪn/\nUK: /ˈæl.paɪn/\n\n高山的 (gāoshān de) - 与高山地区相关的。\n例如：高山滑雪是一项流行的运动 (Alpine skiing is a popular sport)。" },
  { "already", "US: /ɔlˈɹɛdi/\nUK: /ɑlˈɹɛdi/\n\n已经 (yǐjīng) - 表示某事在此之前发生。\n例如：我已经吃过了 (I have already eaten)。" },
  { "also", "US: /ˈɔl.soʊ/\nUK: /ˈɔːl.səʊ/\n\n也 (yě) - 同样地，此外。\n例如：我也喜欢音乐 (I also like music)。" },
  { "alter", "US: /ˈɔl.tɚ/\nUK: /ˈɑl.tɚ/\n\n改变 (gǎibiàn) - 使某物变得不同。\n例如：他们改变了计划 (They altered the plan)。" },
  { "altered", "US: /ˈɔl.tɚd/\nUK: /ˈɑl.tɚd/\n\n改变的 (gǎibiàn de) - 已经修改或改变的。\n例如：这件衣服被改过了 (This dress has been altered)。" },
  { "alternate", "替代的 (tìdài de) - 作为备选的；也指交替。\n例如：我们需要一个替代方案 (We need an alternate plan)。" },
  { "alternative", "US: /ɔl.ˈtɝ.nə.tɪv/\nUK: /ɒl.ˈtɜː(ɹ).nə.tɪv/\n\n替代方案 (tìdài fāng'àn) - 可以选择的另一种可能。\n例如：没有其他选择了 (There is no alternative)。" },
  { "alternatively", "或者 (huòzhě) - 作为另一种选择。\n例如：或者，我们可以坐火车去 (Alternatively, we could take the train)。" },
  { "alternatives", "替代方案 (tìdài fāng'àn) - 替代方案的复数形式。\n例如：我们有几个替代方案 (We have several alternatives)。" },
  { "although", "US: /ɑlˈðoʊ/\nUK: /ɔːlˈðəʊ/\n\n虽然 (suīrán) - 尽管，即使。\n例如：虽然下雨，我们还是去了 (Although it rained, we still went)。" },
  { "alto", "US: /ˈæl.toʊ/\nUK: /ˈæl.təʊ/\n\n中音 (zhōngyīn) - 音乐中的中音声部。\n例如：她唱中音 (She sings alto)。" },
  { "aluminium", "US: /ˌæl(j)uˈmɪn.j.əm/\nUK: /ˌæl.(j)ʊˈmɪn.i.əm/\n\n铝 (lǚ) - 一种轻质金属元素，英式拼写。\n例如：铝箔常用于包装 (Aluminium foil is commonly used for packaging)。" },
  { "aluminum", "US: /ə.ˈluː.mɨ.nəm/\nUK: /ə.ˈluː.mɨ.nəm/\n\n铝 (lǚ) - 一种轻质金属元素，美式拼写。\n例如：这个罐子是铝制的 (This can is made of aluminum)。" },
  { "alumni", "US: /əˈlʌmnaɪ/\nUK: /əˈlʌmnaɪ/\n\n校友 (xiàoyǒu) - 毕业生的复数形式。\n例如：校友会组织了聚会 (The alumni association organized a reunion)。" },
  { "always", "US: /ˈɔl.weɪz/\nUK: /ˈɔː(l).weɪz/\n\n总是 (zǒngshì) - 一直，在所有时间。\n例如：她总是准时 (She is always on time)。" },
  { "amanda", "阿曼达 (Āmàndá) - 常见的英文女性名字。\n例如：阿曼达是我的同事 (Amanda is my colleague)。" },
  { "amateur", "US: /ˈæ.mə.tɚ/\nUK: /ˈæ.mə.tə/\n\n业余爱好者 (yèyú àihàozhě) - 非专业人士。\n例如：他是业余摄影师 (He is an amateur photographer)。" },
  { "amazing", "US: /əˈmeɪzɪŋ/\nUK: /əˈmeɪzɪŋ/\n\n令人惊叹的 (lìng rén jīngtàn de) - 极好的或令人惊讶的。\n例如：这个景色令人惊叹 (The view is amazing)。" },
  { "amazon", "US: /ˈæ.mə.zən/\nUK: /ˈæ.mə.zən/\n\n亚马逊 (Yàmǎxùn) - 南美洲的大河；也指美国电商公司。\n例如：亚马逊是世界上最大的热带雨林 (The Amazon is the world's largest rainforest)。" },
  { "ambassador", "US: /æmˈbæs.ə.də(ɹ)/\nUK: /æmˈbæs.ə.də(ɹ)/\n\n大使 (dàshǐ) - 代表国家的高级外交官。\n例如：他是驻华大使 (He is the ambassador to China)。" },
  { "amber", "US: /ˈæm.bɚ/\nUK: /ˈam.bə/\n\n琥珀色 (hǔpòsè) - 橙黄色；也指琥珀。\n例如：琥珀色的灯光很温暖 (The amber light is warm)。" },
  { "ambien", "安必恩 (Ānbì'ēn) - 一种助眠药物的商品名。\n例如：医生给她开了安必恩 (The doctor prescribed Ambien for her)。" },
  { "ambient", "US: N/A\nUK: /ˈæm.biː.ənt/\n\n周围的 (zhōuwéi de) - 环境的或周围的气氛。\n例如：环境温度很舒适 (The ambient temperature is comfortable)。" },
  { "amend", "US: /əˈmɛnd/\nUK: /əˈmɛnd/\n\n修改 (xiūgǎi) - 对文件或法律进行小的改动。\n例如：他们修改了合同 (They amended the contract)。" },
  { "amended", "修改后的 (xiūgǎi hòu de) - 已经修改的。\n例如：修改后的法案通过了 (The amended bill was passed)。" },
  { "amendment", "US: /ʌˈmɛnd.mənt/\nUK: /ʌˈmɛnd.mənt/\n\n修正案 (xiūzhèng'àn) - 对法律或文件的正式修改。\n例如：宪法修正案保护言论自由 (The constitutional amendment protects free speech)。" },
  { "amendments", "修正案 (xiūzhèng'àn) - 修正案的复数形式。\n例如：提出了多项修正案 (Several amendments were proposed)。" },
  { "amenities", "US: /əˈmɛn.ə.tiːz/\nUK: /əˈmɛn.ə.tiːz/\n\n便利设施 (biànlì shèshī) - 使生活更舒适的设施。\n例如：酒店有很好的便利设施 (The hotel has excellent amenities)。" },
  { "america", "美洲 (Měizhōu) - 指美洲大陆；常指美国。\n例如：哥伦布发现了美洲 (Columbus discovered America)。" },
  { "american", "美国的 (Měiguó de) - 来自或与美国相关的。\n例如：他是美国公民 (He is an American citizen)。" },
  { "americans", "美国人 (Měiguórén) - 美国公民的复数形式。\n例如：许多美国人喜欢棒球 (Many Americans enjoy baseball)。" },
  { "americas", "美洲 (Měizhōu) - 指南北美洲大陆。\n例如：美洲包括许多不同的文化 (The Americas include many different cultures)。" },
  { "amino", "US: /əˈmiːnəʊ/\nUK: /əˈmiːnəʊ/\n\n氨基 (ānjī) - 与氨基酸相关的化学基团。\n例如：氨基酸是蛋白质的组成部分 (Amino acids are components of proteins)。" },
  { "among", "US: /əˈmɒŋ/\nUK: N/A\n\n在...之中 (zài...zhīzhōng) - 被...包围或在一群中。\n例如：他是我们之中最聪明的 (He is the smartest among us)。" },
  { "amongst", "US: /əˈmʌŋst/\nUK: N/A\n\n在...之中 (zài...zhīzhōng) - among的另一种形式，多用于英式英语。\n例如：她在朋友之中很受欢迎 (She is popular amongst her friends)。" },
  { "amount", "US: /əˈmaʊnt/\nUK: N/A\n\n数量 (shùliàng) - 某物的总量或程度。\n例如：金额很大 (The amount is large)。" },
  { "amounts", "US: /əˈmaʊnts/\nUK: /əˈmaʊnts/\n\n数量 (shùliàng) - 数量的复数形式。\n例如：大量的资金被投入 (Large amounts of money were invested)。" },
  { "ampland", "Ampland网站 (Ampland wǎngzhàn) - 一个成人娱乐网站名称。\n例如：这是一个成人网站 (This is an adult website)。" },
  { "amplifier", "US: /ˈæm.plə.faɪ.ə/\nUK: /ˈæm.plə.faɪ.ə/\n\n放大器 (fàngdàqì) - 增强信号或声音的设备。\n例如：这个放大器音质很好 (This amplifier has excellent sound quality)。" },
  { "amsterdam", "阿姆斯特丹 (Āmǔsītèdān) - 荷兰首都。\n例如：阿姆斯特丹以运河闻名 (Amsterdam is famous for its canals)。" },
  { "anaheim", "阿纳海姆 (Ānàhǎimǔ) - 美国加利福尼亚州城市，迪士尼乐园所在地。\n例如：阿纳海姆有著名的迪士尼乐园 (Anaheim has the famous Disneyland)。" },
  { "analog", "US: /ˈæ.nə.lɔɡ/\nUK: /ˈæ.nə.lɑɡ/\n\n模拟的 (mónǐ de) - 使用连续信号的，与数字相对。\n例如：模拟信号比数字信号老旧 (Analog signals are older than digital signals)。" },
  { "analyses", "US: /əˈnæl.ə.siːz/\nUK: /əˈnæl.ə.siːz/\n\n分析 (fēnxī) - 分析的复数形式。\n例如：我们进行了多项分析 (We conducted multiple analyses)。" },
