  { "analyst", "US: /ˈænəlɪst/\nUK: N/A\n\n分析师 (fēnxīshī) - 进行专业分析的人。\n例如：他是一名金融分析师 (He is a financial analyst)。" },
  { "analysts", "分析师 (fēnxīshī) - 分析师的复数形式。\n例如：市场分析师预测价格会上涨 (Market analysts predict prices will rise)。" },
  { "analytical", "US: /æn.əˈlɪt.ə.kəl/\nUK: /æn.əˈlɪt.ə.kəl/\n\n分析的 (fēnxī de) - 与分析相关的或善于分析的。\n例如：她有很强的分析能力 (She has strong analytical skills)。" },
  { "analyze", "US: /ˈæn.ə.laɪz/\nUK: N/A\n\n分析 (fēnxī) - 详细检查或研究。\n例如：我们需要分析这些数据 (We need to analyze this data)。" },
  { "analyzed", "US: /ˈæn.ə.laɪzd/\nUK: /ˈæn.ə.laɪzd/\n\n已分析的 (yǐ fēnxī de) - 已经进行分析的。\n例如：样本已被分析 (The samples have been analyzed)。" },
  { "anatomy", "US: /əˈnætəmi/\nUK: N/A\n\n解剖学 (jiěpōuxué) - 研究生物体结构的学科。\n例如：他学习人体解剖学 (He studies human anatomy)。" },
  { "anchor", "US: /ˈæŋ.kɚ/\nUK: /ˈæŋ.kə/\n\n锚 (máo) - 固定船只的重物；也指新闻主播。\n例如：新闻主播正在播报 (The news anchor is reporting)。" },
  { "ancient", "US: /ˈeɪn.ʃənt/\nUK: N/A\n\n古代的 (gǔdài de) - 非常古老的。\n例如：古代文明很神秘 (Ancient civilizations are mysterious)。" },
  { "andale", "安德利字体 (Āndélì zìtǐ) - 一种无衬线字体的名称。\n例如：我使用安德利字体 (I use the Andale font)。" },
  { "anderson", "安德森 (Āndésēn) - 常见的英文姓氏。\n例如：安德森先生是校长 (Mr. Anderson is the principal)。" },
  { "andorra", "安道尔 (Āndào'ěr) - 欧洲西南部小国。\n例如：安道尔位于西班牙和法国之间 (Andorra is located between Spain and France)。" },
  { "andrea", "安德烈娅 (Āndéliè'yà) - 常见的英文女性名字。\n例如：安德烈娅是设计师 (Andrea is a designer)。" },
  { "andreas", "安德烈亚斯 (Āndéliè'yàsī) - 常见的英文男性名字。\n例如：安德烈亚斯来自德国 (Andreas is from Germany)。" },
