  { "anime", "US: /ˈæn.ɪ.meɪ/\nUK: /ˈæn.ɪ.meɪ/\n\n日本动漫 (Rìběn dòngmàn) - 日本风格的动画。\n例如：他喜欢看动漫 (He likes watching anime)。" },
  { "anna", "US: /ˈænə/\nUK: /ˈænə/\n\n安娜 (Ānnà) - 常见的英文女性名字。\n例如：安娜是我的表姐 (Anna is my cousin)。" },
  { "anne", "安妮 (Ānní) - 常见的英文女性名字。\n例如：《安妮日记》是著名著作 (The Diary of Anne Frank is a famous work)。" },
  { "annex", "US: /əˈnɛks/\nUK: /ˈænɛks/\n\n附件 (fùjiàn) - 附加的建筑或文件；也指吞并。\n例如：文件的附件很重要 (The annex to the document is important)。" },
  { "annie", "安妮 (Ānní) - 常见的英文女性名字，Anne的昵称。\n例如：小安妮很可爱 (Little Annie is cute)。" },
  { "anniversary", "US: /ˌænəˈvɝs(ə)ɹi/\nUK: /ˌænɪˈvɜːs(ə)ɹi/\n\n周年纪念 (zhōunián jìniàn) - 每年重复的纪念日。\n例如：今天是我们的结婚周年纪念日 (Today is our wedding anniversary)。" },
  { "annotated", "注释的 (zhùshì de) - 添加了说明或评论的。\n例如：这是注释版圣经 (This is an annotated Bible)。" },
  { "annotation", "注释 (zhùshì) - 对文本的说明或评论。\n例如：请添加注释 (Please add annotations)。" },
  { "announce", "宣布 (xuānbù) - 公开声明或通知。\n例如：他们宣布了好消息 (They announced good news)。" },
  { "announced", "已宣布的 (yǐ xuānbù de) - 已经公开声明的。\n例如：结果已经宣布了 (The results have been announced)。" },
  { "announcement", "公告 (gōnggào) - 正式的声明或通知。\n例如：学校发布了重要公告 (The school issued an important announcement)。" },
  { "announcements", "公告 (gōnggào) - 公告的复数形式。\n例如：请查看最新公告 (Please check the latest announcements)。" },
  { "announces", "宣布 (xuānbù) - 宣布（第三人称单数）。\n例如：公司宣布了新政策 (The company announces a new policy)。" },
  { "annoying", "令人烦恼的 (lìng rén fánnǎo de) - 使人感到不快的。\n例如：这个噪音很令人烦恼 (This noise is annoying)。" },
  { "annual", "年度的 (niándù de) - 每年一次的。\n例如：年度会议将在下月举行 (The annual meeting will be held next month)。" },
  { "annually", "US: /ˈæn.ju.ə.li/\nUK: /ˈæn.jʊə.li/\n\n每年 (měinián) - 每年一次地。\n例如：会议每年举行一次 (The conference is held annually)。" },
  { "anonymous", "US: /əˈnɒnəməs/\nUK: N/A\n\n匿名的 (nìmíng de) - 不具名的或身份未知的。\n例如：这是一封匿名信 (This is an anonymous letter)。" },
  { "another", "US: /æˈnʌð.ə(ɹ)/\nUK: /æˈnʌð.ə(ɹ)/\n\n另一个 (lìng yīgè) - 额外的一个或不同的一个。\n例如：请再给我一杯咖啡 (Please give me another cup of coffee)。" },
  { "answer", "US: /ˈæn.sɚ/\nUK: /ˈan.sə/\n\n回答 (huídá) - 对问题的回应。\n例如：请回答这个问题 (Please answer this question)。" },
  { "answered", "US: /ænsɜːd/\nUK: N/A\n\n已回答的 (yǐ huídá de) - 已经给出答案的。\n例如：问题已被回答 (The question has been answered)。" },
  { "answering", "US: /ˈæn.sə.ɹɪŋ/\nUK: /ˈɑːn.sə.ɹɪŋ/\n\n回答 (huídá) - 正在回答。\n例如：他正在回答问题 (He is answering questions)。" },
  { "answers", "US: /ˈɑːn.səz/\nUK: /ˈɑːn.səz/\n\n答案 (dá'àn) - 回答的复数形式。\n例如：所有答案都在书后 (All answers are at the back of the book)。" },
  { "antarctica", "南极洲 (Nánjízhōu) - 地球最南端的大陆。\n例如：南极洲是最冷的大陆 (Antarctica is the coldest continent)。" },
  { "antenna", "US: /ænˈtɛn.ə/\nUK: N/A\n\n天线 (tiānxiàn) - 接收或发送无线电信号的装置。\n例如：调整天线以获得更好的信号 (Adjust the antenna for better signal)。" },
  { "anthony", "安东尼 (Āndōngní) - 常见的英文男性名字。\n例如：安东尼是一名律师 (Anthony is a lawyer)。" },
  { "anthropology", "US: /ˌænθɹəˈpɑːlədʒi/\nUK: /ˌænθɹəˈpɒlədʒi/\n\n人类学 (rénlèixué) - 研究人类社会和文化的学科。\n例如：她学习文化人类学 (She studies cultural anthropology)。" },
  { "anti", "US: /ˈæn.ti/\nUK: /ˈæn.ti/\n\n反对 (fǎnduì) - 反对或对抗的前缀。\n例如：反病毒软件 (Anti-virus software)。" },
  { "antibodies", "抗体 (kàngtǐ) - 免疫系统产生的蛋白质的复数形式。\n例如：抗体帮助对抗感染 (Antibodies help fight infections)。" },
  { "antibody", "抗体 (kàngtǐ) - 免疫系统产生的蛋白质。\n例如：身体产生抗体对抗病毒 (The body produces antibodies to fight viruses)。" },
  { "anticipated", "预期的 (yùqī de) - 预先期待或预测的。\n例如：预期的结果已经实现 (The anticipated results have been achieved)。" },
  { "antigua", "安提瓜 (Āntíguā) - 加勒比海岛国安提瓜和巴布达的主岛。\n例如：安提瓜以美丽的海滩闻名 (Antigua is famous for its beautiful beaches)。" },
  { "antique", "US: /ænˈtiːk/\nUK: N/A\n\n古董 (gǔdǒng) - 古老而有价值的物品。\n例如：这个花瓶是古董 (This vase is an antique)。" },
  { "antiques", "US: /ænˈtiːks/\nUK: /ænˈtiːks/\n\n古董 (gǔdǒng) - 古董的复数形式。\n例如：她收集古董家具 (She collects antique furniture)。" },
  { "antivirus", "杀毒软件 (shādú ruǎnjiàn) - 保护计算机免受病毒侵害的软件。\n例如：请安装杀毒软件 (Please install antivirus software)。" },
  { "antonio", "安东尼奥 (Āndōngníàotuō) - 常见的意大利语和西班牙语男性名字。\n例如：安东尼奥来自西班牙 (Antonio is from Spain)。" },
  { "anxiety", "US: /ˌæŋ(ɡ)ˈzaɪ.ə.ti/\nUK: N/A\n\n焦虑 (jiāolǜ) - 担心或紧张的感觉。\n例如：考试前她感到焦虑 (She feels anxiety before exams)。" },
  { "anybody", "US: /ˈɛn.i.bɑd.i/\nUK: /ˈɛn.i.bɒd.i/\n\n任何人 (rènhé rén) - 任何一个人。\n例如：有人在家吗？ (Is anybody home?)。" },
  { "anymore", "US: /ˌɛ.niˈmɔɹ/\nUK: /ˌæ.niˈmoːɹ/\n\n不再 (búzài) - 从某时起不再。\n例如：我不再抽烟了 (I don't smoke anymore)。" },
  { "anyone", "US: /ˈæniˌwʌn/\nUK: N/A\n\n任何人 (rènhé rén) - 任何一个人。\n例如：任何人都可以参加 (Anyone can participate)。" },
  { "anything", "US: /ˈɛn.i.θɪŋ/\nUK: /ˈɛ.nə.θɪŋ/\n\n任何事 (rènhé shì) - 任何东西或事情。\n例如：你需要什么吗？ (Do you need anything?)。" },
  { "anytime", "任何时候 (rènhé shíhòu) - 在任何时间。\n例如：你可以随时打电话给我 (You can call me anytime)。" },
  { "anyway", "US: /ˈɛniweɪ/\nUK: N/A\n\n无论如何 (wúlùn rúhé) - 不管怎样。\n例如：无论如何，我们都要去 (We're going anyway)。" },
  { "anywhere", "US: /ˈɛn.i.(h)wɛɹ/\nUK: /ˈɛn.iː.(h)wɛə(ɹ)/\n\n任何地方 (rènhé dìfang) - 任何一个地方。\n例如：你可以坐在任何地方 (You can sit anywhere)。" },
  { "apache", "阿帕奇 (Āpàqí) - 美洲原住民部落；也指Apache网络服务器软件。\n例如：这个网站使用Apache服务器 (This website uses Apache server)。" },
  { "apart", "US: /əˈpɑɹt/\nUK: /əˈpɑː(ɹ)t/\n\n分开 (fēnkāi) - 彼此分离或相距。\n例如：他们分开住 (They live apart)。" },
  { "apartment", "US: /əˈpɑɹt.mənt/\nUK: /əˈpɑːt.mənt/\n\n公寓 (gōngyù) - 大楼中的一套住房。\n例如：我租了一套公寓 (I rented an apartment)。" },
  { "apartments", "公寓 (gōngyù) - 公寓的复数形式。\n例如：这栋楼有50套公寓 (This building has 50 apartments)。" },
  { "apnic", "亚太网络信息中心 (Yàtài wǎngluò xìnxī zhōngxīn) - 亚太地区的互联网号码注册机构。\n例如：APNIC管理亚太地区的IP地址分配 (APNIC manages IP address allocation in the Asia-Pacific region)。" },
  { "apollo", "US: /əˈpɑloʊ/\nUK: /əˈpɒləʊ/\n\n阿波罗 (Ābōluó) - 希腊神话中的太阳神；也指阿波罗登月计划。\n例如：阿波罗11号首次载人登月 (Apollo 11 was the first manned moon landing)。" },
  { "apparatus", "US: /æ.pəˈɹeɪ.təs/\nUK: /æpəˈɹɑːtəs/\n\n器械 (qìxiè) - 用于特定目的的设备或系统。\n例如：实验室器械很昂贵 (Laboratory apparatus is expensive)。" },
  { "apparel", "US: /əˈpæ.ɹəl/\nUK: N/A\n\n服装 (fúzhuāng) - 衣服和配饰的总称。\n例如：这家店出售运动服装 (This store sells sports apparel)。" },
  { "apparent", "US: /əˈpæ.ɹənt/\nUK: /əˈpæ.ɹənt/\n\n明显的 (míngxiǎn de) - 显而易见的。\n例如：问题很明显 (The problem is apparent)。" },
  { "apparently", "US: /əˈpæɹ.ɨnt.li/\nUK: /əˈpaɹəntli/\n\n显然 (xiǎnrán) - 看起来，似乎。\n例如：显然他不会来了 (Apparently he won't come)。" },
  { "appeal", "US: /əˈpiːl/\nUK: /əˈpiːl/\n\n吸引力 (xīyǐnlì) - 吸引人的品质；也指上诉。\n例如：这个提议很有吸引力 (This proposal has great appeal)。" },
  { "appeals", "上诉 (shàngsù) - 上诉或请求的复数形式。\n例如：法院受理上诉 (The court hears appeals)。" },
  { "appear", "US: /əˈpiɹ/\nUK: /əˈpiːɹ/\n\n出现 (chūxiàn) - 变得可见或开始存在。\n例如：太阳出现了 (The sun appeared)。" },
  { "appearance", "US: /əˈpɪɹəns/\nUK: /əˈpɪəɹəns/\n\n外表 (wàibiǎo) - 外观或出现。\n例如：不要以貌取人 (Don't judge by appearance)。" },
  { "appeared", "US: /əˈpɪɹd/\nUK: /əˈpiːɹd/\n\n出现了 (chūxiàn le) - 已经变得可见。\n例如：问题突然出现了 (The problem suddenly appeared)。" },
  { "appearing", "US: /əˈpɪəɹ.ɪŋ/\nUK: N/A\n\n出现 (chūxiàn) - 正在显现。\n例如：新功能即将出现 (New features are appearing soon)。" },
  { "appears", "US: /əˈpɪɹz/\nUK: /əˈpiːɹz/\n\n看起来 (kànqǐlái) - 似乎，显得（第三人称单数）。\n例如：他看起来很累 (He appears tired)。" },
  { "appendix", "US: /əˈpɛn.dɪks/\nUK: /əˈpɛn.dɪks/\n\n附录 (fùlù) - 书籍末尾的补充材料；也指阑尾。\n例如：详细信息见附录 (See the appendix for details)。" },
  { "apple", "US: /ˈæp.əl/\nUK: /ˈæp.əl/\n\n苹果 (píngguǒ) - 一种水果；也指苹果公司。\n例如：我喜欢吃苹果 (I like eating apples)。" },
  { "appliance", "US: /əˈplaɪəns/\nUK: N/A\n\n电器 (diànqì) - 家用电器设备。\n例如：这个电器很节能 (This appliance is energy-efficient)。" },
  { "appliances", "电器 (diànqì) - 电器的复数形式。\n例如：厨房电器很现代 (Kitchen appliances are modern)。" },
  { "applicable", "US: /əˈplɪkəbəl/\nUK: N/A\n\n适用的 (shìyòng de) - 相关的或可应用的。\n例如：该规则适用于所有人 (This rule is applicable to everyone)。" },
  { "applicant", "US: /ˈæp.lə.kɪnt/\nUK: /ˈæp.lə.kɪnt/\n\n申请人 (shēnqǐngrén) - 申请职位或机会的人。\n例如：所有申请人都需要面试 (All applicants need to be interviewed)。" },
  { "applicants", "申请人 (shēnqǐngrén) - 申请人的复数形式。\n例如：我们收到了100份申请人 (We received 100 applicants)。" },
  { "application", "US: /ˌæpləˈkeɪʃən/\nUK: /aplɪˈkeɪʃ(ə)n/\n\n应用程序 (yìngyòng chéngxù) - 软件应用；也指申请。\n例如：这个应用程序很实用 (This application is very useful)。" },
  { "applications", "US: /ˌæplɪˈkeɪʃənz/\nUK: /ˌæplɪˈkeɪʃənz/\n\n应用 (yìngyòng) - 应用程序或申请的复数形式。\n例如：手机上有很多应用 (There are many applications on the phone)。" },
  { "applied", "US: /əˈplaɪd/\nUK: N/A\n\n应用的 (yìngyòng de) - 已经使用或实施的。\n例如：应用数学很有用 (Applied mathematics is useful)。" },
  { "applies", "适用 (shìyòng) - 应用或适用（第三人称单数）。\n例如：这条规则适用于所有人 (This rule applies to everyone)。" },
  { "apply", "US: /əˈplaɪ/\nUK: N/A\n\n申请 (shēnqǐng) - 提出申请或应用。\n例如：我想申请这份工作 (I want to apply for this job)。" },
  { "applying", "US: /əˈplaɪ.ɪŋ/\nUK: N/A\n\n申请 (shēnqǐng) - 正在申请或应用。\n例如：她正在申请大学 (She is applying to universities)。" },
  { "appointed", "US: /əˈpɔɪntɪd/\nUK: N/A\n\n被任命的 (bèi rènmìng de) - 被正式指定的。\n例如：他被任命为经理 (He was appointed as manager)。" },
  { "appointment", "US: /əˈpɔɪnt.mɛnt/\nUK: /əˈpɔɪnt.mɛnt/\n\n预约 (yùyuē) - 安排的会面时间；也指任命。\n例如：我有医生预约 (I have a doctor's appointment)。" },
  { "appointments", "预约 (yùyuē) - 预约的复数形式。\n例如：今天我有三个预约 (I have three appointments today)。" },
  { "appraisal", "US: /əˈpɹeɪzəl/\nUK: N/A\n\n评估 (pínggū) - 对价值或质量的评定。\n例如：房产评估很重要 (Property appraisal is important)。" },
  { "appreciate", "US: /əˈpɹiː.si.eɪt/\nUK: N/A\n\n感激 (gǎnjī) - 感谢或欣赏。\n例如：我很感激你的帮助 (I appreciate your help)。" },
  { "appreciated", "被感激的 (bèi gǎnjī de) - 受到感谢或重视的。\n例如：你的努力被大家感激 (Your efforts are appreciated)。" },
  { "appreciation", "US: /əˌpɹiː.ʃiˈeɪ.ʃən/\nUK: /əˌpɹiː.ʃiˈeɪ.ʃən/\n\n感激 (gǎnjī) - 感谢或欣赏之情。\n例如：表达感激之情 (Express appreciation)。" },
  { "approach", "US: /əˈpɹoʊt͡ʃ/\nUK: /əˈpɹəʊt͡ʃ/\n\n方法 (fāngfǎ) - 处理问题的方式；也指接近。\n例如：我们需要新的方法 (We need a new approach)。" },
  { "approaches", "方法 (fāngfǎ) - 方法的复数形式；也指接近。\n例如：有多种方法解决这个问题 (There are multiple approaches to this problem)。" },
  { "appropriate", "适当的 (shìdàng de) - 合适的或恰当的。\n例如：请选择适当的时间 (Please choose an appropriate time)。" },
  { "appropriations", "拨款 (bōkuǎn) - 政府预算分配的资金。\n例如：国会批准了拨款 (Congress approved appropriations)。" },
  { "approval", "US: /əˈpɹuvəl/\nUK: /əˈpɹuːvəl/\n\n批准 (pīzhǔn) - 正式同意或认可。\n例如：项目需要获得批准 (The project needs approval)。" },
  { "approve", "US: N/A\nUK: /əˈpɹuːv/\n\n批准 (pīzhǔn) - 正式同意或认可。\n例如：经理批准了这个计划 (The manager approved the plan)。" },
  { "approved", "US: /əˈpɹuːvd/\nUK: N/A\n\n已批准的 (yǐ pīzhǔn de) - 已经得到认可的。\n例如：该药物已被批准使用 (The drug has been approved for use)。" },
  { "approx", "大约 (dàyuē) - approximately的缩写，表示近似。\n例如：大约100人参加 (Approx. 100 people attended)。" },
  { "approximate", "近似的 (jìnsì de) - 接近但不完全准确的。\n例如：这是一个近似值 (This is an approximate value)。" },
  { "approximately", "US: /əˈpɹɒk.sɪ.mət.li/\nUK: /əˈpɹɒk.sɪ.mət.li/\n\n大约 (dàyuē) - 接近某个数量或程度。\n例如：大约需要两小时 (It takes approximately two hours)。" },
  { "apps", "应用程序 (yìngyòng chéngxù) - 应用程序的复数形式或缩写。\n例如：我下载了很多应用 (I downloaded many apps)。" },
  { "april", "四月 (sìyuè) - 一年中的第四个月。\n例如：我的生日在四月 (My birthday is in April)。" },
  { "aqua", "US: /ˈækwə/\nUK: /ˈækwə/\n\n水绿色 (shuǐlǜsè) - 青绿色；也指水。\n例如：这是水绿色的裙子 (This is an aqua dress)。" },
  { "aquarium", "US: /-ɛɹiəm/\nUK: N/A\n\n水族馆 (shuǐzúguǎn) - 展示水生生物的设施；也指鱼缸。\n例如：我们去了水族馆 (We went to the aquarium)。" },
  { "aquatic", "US: /əˈkwæ.tɪk/\nUK: /ɘˈkwɔ.tɘk/\n\n水生的 (shuǐshēng de) - 与水相关的或生活在水中的。\n例如：海豚是水生动物 (Dolphins are aquatic animals)。" },
  { "arab", "阿拉伯的 (Ālābó de) - 与阿拉伯人或文化相关的。\n例如：阿拉伯文化历史悠久 (Arab culture has a long history)。" },
  { "arabia", "阿拉伯 (Ālābó) - 指阿拉伯半岛地区。\n例如：沙特阿拉伯位于阿拉伯半岛 (Saudi Arabia is located in Arabia)。" },
  { "arabic", "阿拉伯语 (Ālābóyǔ) - 阿拉伯人使用的语言。\n例如：她会说阿拉伯语 (She speaks Arabic)。" },
  { "arbitrary", "US: /ˈɑɹ.bɪ.tɹɛ(ə).ɹi/\nUK: /ˈɑɹ.bɪ.tɹɛ(ə).ɹi/\n\n任意的 (rènyì de) - 随意的或武断的。\n例如：这是一个任意的决定 (This is an arbitrary decision)。" },
  { "arbitration", "US: /ˌɑː.bɪˈtɹeɪ.ʃən/\nUK: /ˌɑː.bɪˈtɹeɪ.ʃən/\n\n仲裁 (zhòngcái) - 通过第三方解决争议。\n例如：双方同意接受仲裁 (Both parties agreed to arbitration)。" },
  { "arbor", "树荫处 (shùyīn chù) - 由树木或藤蔓形成的荫蔽处；也指树。\n例如：我们在树荫下休息 (We rested under the arbor)。" },
  { "arcade", "US: /ɑːˈkeɪd/\nUK: /ɑːˈkeɪd/\n\n拱廊 (gǒngláng) - 有拱顶的通道；也指游戏厅。\n例如：商场有游戏厅 (The mall has an arcade)。" },
  { "arch", "US: /ɑɹt͡ʃ/\nUK: /ɑːt͡ʃ/\n\n拱门 (gǒngmén) - 弧形结构；也指主要的。\n例如：建筑有美丽的拱门 (The building has beautiful arches)。" },
  { "architect", "US: /ˈɑɹkɪtɛkt/\nUK: /ˈɑːkɪtɛkt/\n\n建筑师 (jiànzhùshī) - 设计建筑物的专业人员。\n例如：他是一位著名建筑师 (He is a famous architect)。" },
  { "architects", "建筑师 (jiànzhùshī) - 建筑师的复数形式。\n例如：许多建筑师参与了这个项目 (Many architects participated in this project)。" },
  { "architectural", "US: /ˌɑɹkɪˈtɛktjəɹəl/\nUK: /ˌɑɹkɪˈtɛktjəɹəl/\n\n建筑的 (jiànzhù de) - 与建筑设计相关的。\n例如：这座城市有丰富的建筑遗产 (The city has rich architectural heritage)。" },
  { "architecture", "US: /ˈɑɹkɪtɛktʃɚ/\nUK: /ˈɑː.kɪ.ˌtɛk.tʃə/\n\n建筑学 (jiànzhùxué) - 建筑设计的艺术和科学。\n例如：他学习建筑学 (He studies architecture)。" },
  { "archive", "US: /ˈɑɹkaɪv/\nUK: /ˈɑɹkaɪv/\n\n档案 (dàng'àn) - 保存的历史记录或文件。\n例如：文件存放在档案馆 (Documents are kept in the archive)。" },
  { "archived", "已存档的 (yǐ cúndàng de) - 已经保存到档案中的。\n例如：旧邮件已被存档 (Old emails have been archived)。" },
  { "archives", "档案馆 (dàng'ànguǎn) - 保存历史文件的地方。\n例如：国家档案馆保存重要文献 (The national archives preserve important documents)。" },
  { "arctic", "北极的 (Běijí de) - 与北极地区相关的。\n例如：北极熊生活在北极地区 (Polar bears live in the Arctic)。" },
  { "area", "US: /ˈæɹ.i.ə/\nUK: /ˈɛə̯ɹɪə̯/\n\n区域 (qūyù) - 特定的地理空间或范围。\n例如：这个区域很安全 (This area is safe)。" },
  { "areas", "区域 (qūyù) - 区域的复数形式。\n例如：城市有多个商业区域 (The city has multiple commercial areas)。" },
  { "arena", "US: /əˈɹiːnə/\nUK: /əˈɹiːnə/\n\n竞技场 (jìngjìchǎng) - 体育或表演场所；也指活动领域。\n例如：政治竞技场 (The political arena)。" },
  { "argentina", "阿根廷 (Āgēntíng) - 南美洲国家。\n例如：阿根廷以足球和探戈舞闻名 (Argentina is famous for football and tango)。" },
  { "argue", "US: /ˈɑɹ.ɡju/\nUK: /ˈɑː.ɡjuː/\n\n争论 (zhēnglùn) - 提出理由或进行辩论。\n例如：他们在争论这个问题 (They are arguing about this issue)。" },
  { "argued", "争论了 (zhēnglùn le) - 已经进行了辩论。\n例如：律师为客户辩护 (The lawyer argued for the client)。" },
  { "argument", "US: /ˈɑɹɡjumənt/\nUK: /ˈɑːɡjʊmənt/\n\n论点 (lùndiǎn) - 理由或争论。\n例如：他的论点很有说服力 (His argument is convincing)。" },
  { "arguments", "US: /ˈɑɹɡjəmənts/\nUK: /ˈɑːɡjʊmənts/\n\n论点 (lùndiǎn) - 论点或争论的复数形式。\n例如：双方都提出了有力的论点 (Both sides presented strong arguments)。" },
  { "arise", "US: /əˈɹaɪz/\nUK: N/A\n\n出现 (chūxiàn) - 产生或发生。\n例如：问题可能会出现 (Problems may arise)。" },
  { "arising", "US: /əˈɹaɪzɪŋ/\nUK: N/A\n\n产生 (chǎnshēng) - 正在出现或发生。\n例如：由此产生的问题 (Issues arising from this)。" },
  { "arizona", "亚利桑那州 (Yàlìsāngnà zhōu) - 美国西南部的州。\n例如：亚利桑那州有大峡谷 (Arizona has the Grand Canyon)。" },
  { "arkansas", "阿肯色州 (Ākěnsè zhōu) - 美国南部的州。\n例如：阿肯色州的首府是小石城 (The capital of Arkansas is Little Rock)。" },
  { "arlington", "阿灵顿 (Ālíngdùn) - 美国多个城市的名称。\n例如：阿灵顿国家公墓在弗吉尼亚州 (Arlington National Cemetery is in Virginia)。" },
  { "armed", "US: /ɑɹmd/\nUK: /ɑːmd/\n\n武装的 (wǔzhuāng de) - 携带武器的。\n例如：武装部队保卫国家 (Armed forces defend the nation)。" },
  { "armenia", "亚美尼亚 (Yàměiníyà) - 高加索地区国家。\n例如：亚美尼亚有悠久的历史 (Armenia has a long history)。" },
  { "armor", "US: /ˈɑːɹ.mɚ/\nUK: /ˈɑː.mə/\n\n盔甲 (kuījiǎ) - 保护性的金属装备；也指装甲。\n例如：骑士穿着盔甲 (Knights wore armor)。" },
  { "arms", "US: /ɑɹmz/\nUK: /ɑːmz/\n\n武器 (wǔqì) - 武器或手臂的复数形式。\n例如：军备控制很重要 (Arms control is important)。" },
  { "armstrong", "阿姆斯特朗 (Āmǔsītèlǎng) - 常见的英文姓氏。\n例如：尼尔·阿姆斯特朗是首位登月的人 (Neil Armstrong was the first person to walk on the moon)。" },
  { "army", "US: /ˈɑɹ.mi/\nUK: /ˈɑː.miː/\n\n军队 (jūnduì) - 国家的陆军或武装力量。\n例如：他在军队服役 (He serves in the army)。" },
  { "arnold", "阿诺德 (Ānuòdé) - 常见的英文男性名字。\n例如：阿诺德·施瓦辛格是著名演员 (Arnold Schwarzenegger is a famous actor)。" },
  { "around", "US: /əˈɹaʊnd/\nUK: /əˈɹaʊnd/\n\n在周围 (zài zhōuwéi) - 环绕或大约。\n例如：环游世界 (Travel around the world)。" },
  { "arrange", "US: /əˈɹeɪndʒ/\nUK: N/A\n\n安排 (ānpái) - 组织或整理。\n例如：请安排一次会议 (Please arrange a meeting)。" },
  { "arranged", "US: /əˈɹeɪndʒd/\nUK: N/A\n\n安排好的 (ānpái hǎo de) - 已经组织或整理的。\n例如：一切都安排好了 (Everything is arranged)。" },
  { "arrangement", "US: /əˈɹeɪnd͡ʒmənt/\nUK: N/A\n\n安排 (ānpái) - 组织或布置的方式。\n例如：这个安排很合理 (This arrangement is reasonable)。" },
  { "arrangements", "US: /əˈɹeɪnd͡ʒmənts/\nUK: N/A\n\n安排 (ānpái) - 安排的复数形式。\n例如：旅行安排已经完成 (Travel arrangements are complete)。" },
  { "array", "US: /əˈɹeɪ/\nUK: N/A\n\n数组 (shùzǔ) - 有序排列的事物；计算机中的数据结构。\n例如：这是一个整数数组 (This is an array of integers)。" },
  { "arrest", "US: /əˈɹɛst/\nUK: N/A\n\n逮捕 (dàibǔ) - 拘留或扣押。\n例如：警察逮捕了嫌疑人 (Police arrested the suspect)。" },
  { "arrested", "US: /əˈɹɛstɪd/\nUK: N/A\n\n被逮捕的 (bèi dàibǔ de) - 已经被拘留的。\n例如：他被逮捕了 (He was arrested)。" },
  { "arrival", "US: /əˈɹaɪ.vəl/\nUK: /əˈɹaɪ.vəl/\n\n到达 (dàodá) - 抵达某地的行为或时刻。\n例如：预计到达时间是下午三点 (The estimated arrival time is 3 PM)。" },
  { "arrivals", "US: /əˈɹaɪvəlz/\nUK: /əˈɹaɪvəlz/\n\n到达 (dàodá) - 到达的复数形式；也指到达大厅。\n例如：国际到达在二楼 (International arrivals are on the second floor)。" },
  { "arrive", "US: /əˈɹaɪv/\nUK: N/A\n\n到达 (dàodá) - 抵达目的地。\n例如：我们什么时候到达？ (When will we arrive?)。" },
  { "arrived", "US: /əˈɹaɪvd/\nUK: N/A\n\n到达了 (dàodá le) - 已经抵达。\n例如：包裹已经到达 (The package has arrived)。" },
  { "arrives", "US: /əˈɹaɪvz/\nUK: /əˈɹaɪvz/\n\n到达 (dàodá) - 到达（第三人称单数）。\n例如：火车准时到达 (The train arrives on time)。" },
  { "arrow", "箭头 (jiàntóu) - 箭或指示方向的符号。\n例如：跟随箭头指示 (Follow the arrow)。" },
  { "arthritis", "US: /ɑː(ɹ)θˈɹaɪtɪs/\nUK: /ɑː(ɹ)θˈɹaɪtɪs/\n\n关节炎 (guānjiéyán) - 关节的炎症性疾病。\n例如：老年人容易患关节炎 (Elderly people are prone to arthritis)。" },
  { "arthur", "亚瑟 (Yàsè) - 常见的英文男性名字。\n例如：亚瑟王是传奇人物 (King Arthur is a legendary figure)。" },
  { "article", "US: /ˈɑɹtəkl̩/\nUK: /ˈɑːtɪkəl/\n\n文章 (wénzhāng) - 书面作品；也指物品或冠词。\n例如：我读了一篇有趣的文章 (I read an interesting article)。" },
  { "articles", "US: /ˈɑɹtɪkəlz/\nUK: /ˈɑːtɪkəlz/\n\n文章 (wénzhāng) - 文章的复数形式。\n例如：这本杂志有很多文章 (This magazine has many articles)。" },
  { "artificial", "US: /ɑː(ɹ)təˈfɪʃəl/\nUK: N/A\n\n人工的 (réngōng de) - 人造的，非自然的。\n例如：人工智能正在发展 (Artificial intelligence is developing)。" },
  { "artist", "US: /ˈɑɹ.tɪst/\nUK: /ˈɑːtɪst/\n\n艺术家 (yìshùjiā) - 创作艺术作品的人。\n例如：她是一位才华横溢的艺术家 (She is a talented artist)。" },
  { "artistic", "US: /ɑːˈtɪstɪk/\nUK: /ɑːˈtɪstɪk/\n\n艺术的 (yìshù de) - 与艺术相关的或有艺术才能的。\n例如：他有艺术天赋 (He has artistic talent)。" },
  { "artists", "US: /ˈɑɹ.tɪsts/\nUK: /ˈɑːtɪsts/\n\n艺术家 (yìshùjiā) - 艺术家的复数形式。\n例如：许多艺术家参加了展览 (Many artists participated in the exhibition)。" },
  { "arts", "US: /ɑɹts/\nUK: /ɑːts/\n\n艺术 (yìshù) - 各种艺术形式的总称。\n例如：艺术与科学都很重要 (Both arts and sciences are important)。" },
  { "artwork", "US: /ˈɑːtˌwɜːk/\nUK: /ˈɑːtˌwɜːk/\n\n艺术品 (yìshùpǐn) - 艺术作品。\n例如：这幅艺术品很珍贵 (This artwork is precious)。" },
  { "aruba", "阿鲁巴 (Ālǔbā) - 加勒比海岛屿，荷兰王国的自治国。\n例如：阿鲁巴是旅游胜地 (Aruba is a tourist destination)。" },
  { "asbestos", "US: /æs.ˈbɛs.tɒs/\nUK: /æs.ˈbɛs.tɒs/\n\n石棉 (shímián) - 一种纤维状矿物，现已知有害。\n例如：石棉对健康有害 (Asbestos is harmful to health)。" },
  { "ascii", "ASCII码 (ASCII mǎ) - 美国信息交换标准代码，字符编码标准。\n例如：ASCII码用于文本编码 (ASCII is used for text encoding)。" },
  { "ashley", "阿什利 (Āshílì) - 常见的英文名字，可用于男女。\n例如：阿什利是我的朋友 (Ashley is my friend)。" },
  { "asia", "亚洲 (Yàzhōu) - 世界最大的洲。\n例如：亚洲有许多古老文明 (Asia has many ancient civilizations)。" },
  { "asian", "亚洲的 (Yàzhōu de) - 来自或与亚洲相关的。\n例如：亚洲文化非常多样 (Asian culture is very diverse)。" },
  { "aside", "US: /əˈsaɪd/\nUK: N/A\n\n在旁边 (zài pángbiān) - 到一边或除了。\n例如：把问题放在一边 (Put the issue aside)。" },
  { "asin", "亚马逊标准识别号 (Yàmǎxùn biāozhǔn shíbié hào) - Amazon Standard Identification Number的缩写。\n例如：每个产品都有唯一的ASIN码 (Each product has a unique ASIN)。" },
  { "asked", "US: /ˈæskt/\nUK: /ˈɑːskt/\n\n问了 (wèn le) - 已经提出问题。\n例如：他问了一个好问题 (He asked a good question)。" },
  { "asking", "US: /ˈeəskɪŋ/\nUK: /ˈɑːskɪŋ/\n\n询问 (xúnwèn) - 正在提问。\n例如：他正在询问价格 (He is asking about the price)。" },
  { "asks", "US: /æsks/\nUK: /ɑːsks/\n\n问 (wèn) - 询问（第三人称单数）。\n例如：她问了很多问题 (She asks many questions)。" },
  { "aspect", "US: /ˈæspɛkt/\nUK: N/A\n\n方面 (fāngmiàn) - 事物的某一部分或角度。\n例如：从各个方面考虑 (Consider all aspects)。" },
  { "aspects", "US: /ˈæspɛkts/\nUK: N/A\n\n方面 (fāngmiàn) - 方面的复数形式。\n例如：生活的各个方面 (Various aspects of life)。" },
  { "assault", "US: /əˈsɔːlt/\nUK: N/A\n\n袭击 (xíjī) - 暴力攻击的行为。\n例如：他被指控袭击罪 (He was charged with assault)。" },
  { "assembled", "US: /əˈsɛmbl̩d/\nUK: N/A\n\n组装的 (zǔzhuāng de) - 已经聚集或组合的。\n例如：家具已组装完毕 (The furniture has been assembled)。" },
  { "assembly", "US: /əˈsɛmb.li/\nUK: /əˈsɛmb.lɪ/\n\n集会 (jíhuì) - 聚集或组装；也指议会。\n例如：学校举行集会 (The school held an assembly)。" },
  { "assess", "US: /əˈsɛs/\nUK: N/A\n\n评估 (pínggū) - 评价或估计。\n例如：评估损失 (Assess the damage)。" },
  { "assessed", "US: /əˈsɛst/\nUK: /əˈsɛst/\n\n已评估的 (yǐ pínggū de) - 已经进行评价的。\n例如：风险已被评估 (The risk has been assessed)。" },
  { "assessing", "US: /əˈsɛsɪŋ/\nUK: /əˈsɛsɪŋ/\n\n评估 (pínggū) - 正在进行评价。\n例如：我们正在评估情况 (We are assessing the situation)。" },
  { "assessment", "评估 (pínggū) - 评价的过程或结果。\n例如：需求评估很重要 (Needs assessment is important)。" },
  { "assessments", "评估 (pínggū) - 评估的复数形式。\n例如：进行多次评估 (Conduct multiple assessments)。" },
  { "asset", "资产 (zīchǎn) - 有价值的财产或优势。\n例如：房产是重要资产 (Real estate is an important asset)。" },
  { "assets", "US: /ˈæsets/\nUK: /ˈæsets/\n\n资产 (zīchǎn) - 资产的复数形式。\n例如：公司资产总额很高 (The company's total assets are high)。" },
  { "assign", "US: /əˈsaɪn/\nUK: N/A\n\n分配 (fēnpèi) - 指定或分派任务。\n例如：老师分配了作业 (The teacher assigned homework)。" },
  { "assigned", "US: /əˈsaɪnd/\nUK: N/A\n\n分配的 (fēnpèi de) - 已经指定的。\n例如：任务已被分配 (Tasks have been assigned)。" },
  { "assignment", "任务 (rènwù) - 分配的工作或作业。\n例如：这个任务很难 (This assignment is difficult)。" },
  { "assignments", "作业 (zuòyè) - 任务的复数形式。\n例如：我有很多作业 (I have many assignments)。" },
  { "assist", "US: /əˈsɪst/\nUK: N/A\n\n协助 (xiézhù) - 帮助或支持。\n例如：我会协助你完成 (I will assist you to complete it)。" },
  { "assistance", "US: /əˈsɪs.təns/\nUK: /əˈsɪs.təns/\n\n帮助 (bāngzhù) - 援助或支持。\n例如：需要帮助吗？ (Do you need assistance?)。" },
  { "assistant", "US: /əˈsɪstənt/\nUK: N/A\n\n助手 (zhùshǒu) - 帮助他人的人。\n例如：她是经理助理 (She is the manager's assistant)。" },
  { "assisted", "US: /əˈsɪstɪd/\nUK: N/A\n\n协助的 (xiézhù de) - 已经得到帮助的。\n例如：他得到了医生的协助 (He was assisted by the doctor)。" },
  { "assists", "US: /əˈsɪsts/\nUK: /əˈsɪsts/\n\n协助 (xiézhù) - 帮助（第三人称单数）。\n例如：他协助团队完成项目 (He assists the team in completing the project)。" },
  { "associate", "US: /əˈsoʊsi.ət/\nUK: /əˈsəʊsi.ət/\n\n同事 (tóngshì) - 伙伴或联系；也指副职。\n例如：他是我的同事 (He is my associate)。" },
  { "associated", "US: /əˈsoʊsieɪtɪd/\nUK: /əˈsəʊsieɪtɪd/\n\n相关的 (xiāngguān de) - 有联系的。\n例如：相关风险 (Associated risks)。" },
  { "associates", "US: /əˈsoʊsi.əts/\nUK: /əˈsəʊsi.əts/\n\n同事 (tóngshì) - 同事的复数形式。\n例如：他和同事们一起工作 (He works with his associates)。" },
  { "association", "US: /əˌsoʊsiˈeɪʃən/\nUK: /əˌsəʊsiˈeɪʃən/\n\n协会 (xiéhuì) - 组织或联系。\n例如：律师协会 (Bar association)。" },
  { "associations", "US: /əˌsoʊsiˈeɪʃənz/\nUK: /əˌsəʊsiˈeɪʃənz/\n\n协会 (xiéhuì) - 协会的复数形式。\n例如：专业协会很多 (There are many professional associations)。" },
  { "assume", "US: /əˈsuːm/\nUK: /əˈsjuːm/\n\n假设 (jiǎshè) - 认为或承担。\n例如：我假设你同意 (I assume you agree)。" },
  { "assumed", "假定的 (jiǎdìng de) - 被认为是真实的。\n例如：假定条件 (Assumed conditions)。" },
  { "assumes", "假设 (jiǎshè) - 假设（第三人称单数）。\n例如：理论假设某些条件 (The theory assumes certain conditions)。" },
  { "assuming", "US: /əˈsjuːmɪŋ/\nUK: /əˈsjuːmɪŋ/\n\n假设 (jiǎshè) - 假定或承担。\n例如：假设一切顺利 (Assuming everything goes well)。" },
  { "assumption", "US: /əˈsʌmp.ʃən/\nUK: N/A\n\n假设 (jiǎshè) - 未经证实就认为真实的事。\n例如：这个假设需要验证 (This assumption needs verification)。" },
  { "assumptions", "假设 (jiǎshè) - 假设的复数形式。\n例如：基本假设 (Basic assumptions)。" },
  { "assurance", "US: /əˈʃɝəns/\nUK: /əˈʃɔːɹəns/\n\n保证 (bǎozhèng) - 确定或保险。\n例如：质量保证 (Quality assurance)。" },
  { "assure", "US: /əˈʃɝ/\nUK: /əˈʃɔː/\n\n保证 (bǎozhèng) - 使确信或承诺。\n例如：我向你保证 (I assure you)。" },
  { "assured", "US: /əˈʃɝd/\nUK: /əˈʃɔːd/\n\n确信的 (quèxìn de) - 有把握的或保证的。\n例如：成功是有保证的 (Success is assured)。" },
  { "asthma", "US: /ˈasmə/\nUK: /ˈasmə/\n\n哮喘 (xiàochuǎn) - 一种呼吸系统疾病。\n例如：他患有哮喘 (He has asthma)。" },
  { "astrology", "US: /əˈstɹɒlədʒi/\nUK: /əˈstɹɒlədʒi/\n\n占星术 (zhānxīngshù) - 通过天体位置预测的学问。\n例如：占星术在古代很流行 (Astrology was popular in ancient times)。" },
  { "astronomy", "US: /æˈstɹɑnəˌmi/\nUK: N/A\n\n天文学 (tiānwénxué) - 研究天体的科学。\n例如：他学习天文学 (He studies astronomy)。" },
  { "asus", "华硕 (Huáshuò) - 台湾电脑硬件公司。\n例如：华硕生产主板和笔记本电脑 (Asus produces motherboards and laptops)。" },
  { "asylum", "US: /əˈsaɪləm/\nUK: N/A\n\n庇护 (bìhù) - 保护或避难所。\n例如：申请政治庇护 (Apply for political asylum)。" },
  { "athens", "雅典 (Yǎdiǎn) - 希腊首都。\n例如：雅典是古代文明的摇篮 (Athens is the cradle of ancient civilization)。" },
  { "athletes", "运动员 (yùndòngyuán) - 运动员的复数形式。\n例如：奥运会有来自世界各地的运动员 (The Olympics has athletes from around the world)。" },
  { "athletic", "US: /æθˈlɛt.ɪk/\nUK: /æθˈlɛt.ɪk/\n\n运动的 (yùndòng de) - 与体育相关的或身体强健的。\n例如：他很有运动天赋 (He is athletic)。" },
  { "athletics", "US: /æθˈlɛtɪks/\nUK: /æθˈlɛtɪks/\n\n田径运动 (tiánjìng yùndòng) - 体育运动，尤指田径。\n例如：田径运动包括跑步和跳跃 (Athletics includes running and jumping)。" },
  { "atlanta", "亚特兰大 (Yàtèlándà) - 美国佐治亚州首府。\n例如：亚特兰大举办过奥运会 (Atlanta hosted the Olympics)。" },
  { "atlantic", "大西洋 (Dàxīyáng) - 世界第二大洋。\n例如：大西洋分隔欧洲和美洲 (The Atlantic Ocean separates Europe and the Americas)。" },
  { "atlas", "US: /ˈætləs/\nUK: /ˈætləs/\n\n地图集 (dìtújí) - 地图的集合；也指希腊神话中的巨人。\n例如：世界地图集 (World atlas)。" },
  { "atmosphere", "US: /ˈætməsˌfɪɹ/\nUK: /ˈæt.məsˌfɪə(ɹ)/\n\n大气层 (dàqìcéng) - 围绕地球的气体层；也指氛围。\n例如：派对的气氛很好 (The atmosphere at the party was great)。" },
